CREATE FUNCTION private.log_sensitive_data_access(p_table_name text, p_row_ref text, p_action text DEFAULT 'select'::text, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $$
begin
  insert into public.sensitive_data_access_audit (
    actor_auth_user_id,
    actor_hr_id,
    actor_role,
    action,
    table_name,
    row_ref,
    reason
  )
  values (
    (select auth.uid()),
    private.phx_current_hr_id(),
    private.phx_current_role(),
    coalesce(nullif(trim(p_action), ''), 'select'),
    coalesce(nullif(trim(p_table_name), ''), 'unknown'),
    nullif(trim(coalesce(p_row_ref, '')), ''),
    nullif(trim(coalesce(p_reason, '')), '')
  );
end;
$$;


