--
-- TOC entry 788 (class 1255 OID 16525)
-- Name: phx_reserve_offer_employee_hr_id_v2(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.phx_reserve_offer_employee_hr_id_v2(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $_$
declare
  v_offer public.job_offers%rowtype;
  v_prefix text := 'PH';
  v_line_name text;
  v_line_code text;
  v_candidate integer;
  v_employee_hr_id text;
  v_attempt integer := 0;
begin
  perform pg_advisory_xact_lock(hashtext('phx_offer_hr_id_generation'));

  select *
    into v_offer
  from public.job_offers
  where id = p_offer_id
  for update;

  if not found then
    raise exception 'Offer not found.';
  end if;

  v_employee_hr_id := nullif(trim(coalesce(v_offer.reserved_employee_hr_id, v_offer.employee_hr_id, '')), '');

  if v_employee_hr_id is not null then
    return jsonb_build_object(
      'employee_hr_id', v_employee_hr_id,
      'offer_id', v_offer.id
    );
  end if;

  if v_offer.status not in ('sent', 'accepted') then
    raise exception 'Only sent or accepted offers can reserve an employee HR ID.';
  end if;

  if v_offer.line_id is not null then
    select coalesce(name, ''), coalesce(code, '')
      into v_line_name, v_line_code
    from public.lines
    where id = v_offer.line_id;

    if position('anti' in lower(v_line_name || ' ' || v_line_code)) > 0 then
      v_prefix := 'AI';
    elsif position('pedia' in lower(v_line_name || ' ' || v_line_code)) > 0 then
      v_prefix := 'PD';
    elsif position('cns' in lower(v_line_name || ' ' || v_line_code)) > 0 then
      v_prefix := 'CN';
    elsif position('office' in lower(v_line_name || ' ' || v_line_code)) > 0 then
      v_prefix := 'OF';
    end if;
  end if;

  loop
    v_attempt := v_attempt + 1;
    if v_attempt > 10 then
      raise exception 'Failed to reserve a unique HR_ID for prefix %.', v_prefix;
    end if;

    select coalesce(max(candidate), 0) + 1
      into v_candidate
    from (
      select nullif(substring(upper(hr_id) from ('^' || v_prefix || '-([0-9]+)$')), '')::integer as candidate
      from public.employees
      where upper(hr_id) like v_prefix || '-%'
      union all
      select nullif(substring(upper(reserved_employee_hr_id) from ('^' || v_prefix || '-([0-9]+)$')), '')::integer as candidate
      from public.job_offers
      where reserved_employee_hr_id is not null
        and upper(reserved_employee_hr_id) like v_prefix || '-%'
      union all
      select nullif(substring(upper(employee_hr_id) from ('^' || v_prefix || '-([0-9]+)$')), '')::integer as candidate
      from public.job_offers
      where employee_hr_id is not null
        and upper(employee_hr_id) like v_prefix || '-%'
    ) ids
    where candidate is not null;

    v_employee_hr_id := v_prefix || '-' || lpad(v_candidate::text, 4, '0');

    begin
      update public.job_offers
      set reserved_employee_hr_id = v_employee_hr_id,
          updated_at = now()
      where id = v_offer.id;
      exit;
    exception
      when unique_violation then
        v_employee_hr_id := null;
    end;
  end loop;

  insert into public.job_offer_audit_logs (
    offer_id, action, actor_type, actor_reference, details
  ) values (
    v_offer.id,
    'employee_hr_id_reserved',
    'system',
    null,
    jsonb_build_object('employeeHrId', v_employee_hr_id)
  );

  return jsonb_build_object(
    'employee_hr_id', v_employee_hr_id,
    'offer_id', v_offer.id
  );
end;
$_$;


--
-- TOC entry 789 (class 1255 OID 16526)
-- Name: accept_offer_and_create_employee(uuid, text, date, date, date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_offer_and_create_employee(p_offer_id uuid, p_hr_id text, p_hire_date date DEFAULT NULL::date, p_birth_date date DEFAULT NULL::date, p_contract_start_date date DEFAULT NULL::date, p_contract_renewal_date date DEFAULT NULL::date, p_probation_end_date date DEFAULT NULL::date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  o record;
  v_hire_date date;
  v_hr_id text;
begin
  select * into o
  from public.job_offers
  where id = p_offer_id;

  if not found then
    raise exception 'Offer % not found', p_offer_id;
  end if;

  if o.status not in ('sent','accepted') then
    raise exception 'Offer % is not in a valid status for acceptance. Current status: %', p_offer_id, o.status;
  end if;

  v_hr_id := trim(p_hr_id);
  if v_hr_id is null or v_hr_id = '' then
    raise exception 'HR_ID is required';
  end if;

  if exists (select 1 from public.employees where hr_id = v_hr_id)
     and coalesce(o.employee_hr_id, '') <> v_hr_id then
    raise exception 'HR_ID % already exists in employees', v_hr_id;
  end if;

  v_hire_date := coalesce(p_hire_date, o.start_date, current_date);

  insert into public.employees (
    hr_id,
    full_name,
    work_email,
    mobile_number,
    job_title,
    hire_date,
    employment_status,
    manager_hr_id,
    department_id,
    line_id,
    area_id,
    position_id,
    birth_date,
    contract_start_date,
    contract_renewal_date,
    probation_end_date,
    onboarding_source,
    onboarding_status,
    payroll_eligible,
    organogram_visible,
    created_at,
    updated_at
  )
  values (
    v_hr_id,
    o.candidate_name,
    o.candidate_email,
    o.candidate_phone,
    o.job_title,
    v_hire_date,
    'active',
    o.manager_hr_id,
    o.department_id,
    o.line_id,
    o.area_id,
    o.position_id,
    p_birth_date,
    coalesce(p_contract_start_date, v_hire_date),
    p_contract_renewal_date,
    p_probation_end_date,
    'job_offer',
    'active',
    true,
    true,
    now(),
    now()
  )
  on conflict (hr_id) do update
  set
    full_name = excluded.full_name,
    work_email = excluded.work_email,
    mobile_number = excluded.mobile_number,
    job_title = excluded.job_title,
    hire_date = excluded.hire_date,
    employment_status = 'active',
    manager_hr_id = excluded.manager_hr_id,
    department_id = excluded.department_id,
    line_id = excluded.line_id,
    area_id = excluded.area_id,
    position_id = excluded.position_id,
    birth_date = coalesce(excluded.birth_date, public.employees.birth_date),
    contract_start_date = coalesce(excluded.contract_start_date, public.employees.contract_start_date),
    contract_renewal_date = coalesce(excluded.contract_renewal_date, public.employees.contract_renewal_date),
    probation_end_date = coalesce(excluded.probation_end_date, public.employees.probation_end_date),
    onboarding_source = 'job_offer',
    onboarding_status = 'active',
    payroll_eligible = true,
    organogram_visible = true,
    updated_at = now();

  insert into public.employee_compensation (
    employee_hr_id,
    gross_salary,
    net_salary,
    created_at,
    updated_at
  )
  values (
    v_hr_id,
    o.salary_amount,
    o.salary_amount,
    now(),
    now()
  )
  on conflict (employee_hr_id) do update
  set
    gross_salary = coalesce(excluded.gross_salary, public.employee_compensation.gross_salary),
    net_salary = coalesce(excluded.net_salary, public.employee_compensation.net_salary),
    updated_at = now();

  insert into public.employee_history (
    employee_hr_id,
    event_type,
    effective_from,
    department_id,
    line_id,
    area_id,
    position_id,
    note,
    created_at
  )
  values (
    v_hr_id,
    'hired_from_offer',
    v_hire_date,
    o.department_id,
    o.line_id,
    o.area_id,
    o.position_id,
    'Created from accepted job offer ' || coalesce(o.offer_code, o.id::text),
    now()
  );

  update public.job_offers
  set
    status = 'accepted',
    accepted_at = coalesce(accepted_at, now()),
    employee_hr_id = v_hr_id,
    onboarding_status = 'employee_created',
    updated_at = now()
  where id = p_offer_id;

  insert into public.job_offer_audit_logs (offer_id, action, actor_type, actor_reference, details, created_at)
  values (
    p_offer_id,
    'employee_created',
    'system',
    v_hr_id,
    jsonb_build_object('hr_id', v_hr_id, 'hire_date', v_hire_date),
    now()
  );

  perform public.generate_employee_lifecycle_notifications(v_hr_id);

  return v_hr_id;
end;
$$;


