--
-- TOC entry 790 (class 1255 OID 16542)
-- Name: acknowledge_coaching_report(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_coaching_report(p_report_id uuid, p_employee_hr_id text, p_acknowledgment_text text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text) RETURNS public.coaching_reports
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_report public.coaching_reports%rowtype;
  v_updated public.coaching_reports%rowtype;
begin
  select *
  into v_report
  from public.coaching_reports
  where id = p_report_id
  for update;

  if not found then
    raise exception 'Coaching report was not found.';
  end if;

  if upper(btrim(v_report.medical_rep_hr_id)) <> upper(btrim(p_employee_hr_id)) then
    raise exception 'Forbidden: employees can only acknowledge their own coaching reports.';
  end if;

  if v_report.status <> 'submitted' then
    raise exception 'Only submitted coaching reports can be acknowledged.';
  end if;

  insert into public.coaching_report_acknowledgments (
    report_id,
    employee_hr_id,
    acknowledgment_text,
    ip_address,
    user_agent
  )
  values (
    p_report_id,
    v_report.medical_rep_hr_id,
    coalesce(nullif(btrim(p_acknowledgment_text), ''), 'I acknowledge and submit this coaching report review.'),
    nullif(btrim(p_ip_address), ''),
    nullif(btrim(p_user_agent), '')
  );

  update public.coaching_reports
  set
    acknowledged_at = now(),
    employee_acknowledged = true,
    status = 'reviewed_by_employee',
    updated_by = p_employee_hr_id
  where id = p_report_id
  returning *
  into v_updated;

  insert into public.coaching_report_audit_logs (
    report_id,
    actor_hr_id,
    action,
    old_values,
    new_values,
    metadata
  )
  values (
    p_report_id,
    p_employee_hr_id,
    'acknowledged',
    jsonb_build_object('status', v_report.status),
    jsonb_build_object('status', 'reviewed_by_employee', 'acknowledgedAt', v_updated.acknowledged_at),
    jsonb_build_object('acknowledgmentText', coalesce(nullif(btrim(p_acknowledgment_text), ''), 'I acknowledge and submit this coaching report review.'))
  );

  return v_updated;
exception
  when unique_violation then
    raise exception 'This coaching report has already been acknowledged.';
end;
$$;


--
-- TOC entry 791 (class 1255 OID 16543)
-- Name: analytics_closing_by_employee(text, text, text, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.analytics_closing_by_employee(p_period text DEFAULT NULL::text, p_period_from text DEFAULT NULL::text, p_period_to text DEFAULT NULL::text, p_lines text[] DEFAULT NULL::text[], p_employee_hr_id text DEFAULT NULL::text, p_territory text DEFAULT NULL::text) RETURNS TABLE(period text, year integer, month integer, batch_id uuid, line text, employee_hr_id text, employee_name text, manager_hr_id text, territory text, sales_value numeric, target_value numeric, sales_units numeric, target_units numeric, achievement_pct numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'analytics', 'public'
    AS $$
  select period, year, month, batch_id, line,
         employee_hr_id, employee_name, manager_hr_id, territory,
         sum(sales_value)   as sales_value,
         sum(target_value)  as target_value,
         sum(sales_units)   as sales_units,
         sum(target_units)  as target_units,
         case when sum(target_value) > 0
              then round((sum(sales_value) / sum(target_value) * 100)::numeric, 2)
              else null end  as achievement_pct
  from   analytics.closing_fact
  where  (p_period is null        or period = p_period)
    and  (p_period_from is null   or period >= p_period_from)
    and  (p_period_to is null     or period <= p_period_to)
    and  (p_lines is null         or line = any(p_lines))
    and  (p_employee_hr_id is null or upper(btrim(employee_hr_id)) = upper(btrim(p_employee_hr_id)))
    and  (p_territory is null     or lower(btrim(territory)) like '%' || lower(btrim(p_territory)) || '%')
  group by period, year, month, batch_id, line, employee_hr_id, employee_name, manager_hr_id, territory
  order by period, line, sales_value desc;
$$;


