--
-- TOC entry 800 (class 1255 OID 16552)
-- Name: api_rate_limit_consume(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.api_rate_limit_consume(p_bucket_key text, p_limit integer, p_window_ms integer) RETURNS TABLE(allowed boolean, retry_after_seconds integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_reset_at timestamptz := now() + ((greatest(p_window_ms, 1)::double precision / 1000.0) * interval '1 second');
  v_count integer;
  v_current_reset_at timestamptz;
begin
  insert into public.api_rate_limit_buckets (bucket_key, request_count, reset_at, updated_at)
  values (p_bucket_key, 1, v_reset_at, v_now)
  on conflict (bucket_key) do update
  set request_count = case
        when public.api_rate_limit_buckets.reset_at <= v_now then 1
        else public.api_rate_limit_buckets.request_count + 1
      end,
      reset_at = case
        when public.api_rate_limit_buckets.reset_at <= v_now then v_reset_at
        else public.api_rate_limit_buckets.reset_at
      end,
      updated_at = v_now
  returning request_count, reset_at
  into v_count, v_current_reset_at;

  allowed := v_count <= p_limit;
  retry_after_seconds := case
    when allowed then 0
    else greatest(1, ceil(extract(epoch from (v_current_reset_at - v_now)))::integer)
  end;
  return next;
end;
$$;


--
-- TOC entry 801 (class 1255 OID 16553)
-- Name: create_lifecycle_notification_event(text, text, date, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_lifecycle_notification_event(p_category text, p_employee_hr_id text, p_scheduled_for date, p_subject text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_event_key text;
begin
  if p_employee_hr_id is null or p_scheduled_for is null then
    return null;
  end if;

  v_event_key := p_category || ':' || p_employee_hr_id || ':' || p_scheduled_for::text;

  insert into public.notification_events (
    event_key,
    category,
    employee_hr_id,
    scheduled_for,
    recipients,
    subject,
    status,
    metadata,
    created_at,
    updated_at
  )
  values (
    v_event_key,
    p_category,
    p_employee_hr_id,
    p_scheduled_for,
    '{}'::text[],
    p_subject,
    'pending',
    coalesce(p_metadata, '{}'::jsonb),
    now(),
    now()
  )
  on conflict (event_key) do update
  set
    subject = excluded.subject,
    metadata = excluded.metadata,
    updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;


