--
-- TOC entry 824 (class 1255 OID 16578)
-- Name: fn_get_command_center_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_command_center_metrics() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_payroll_batch record;
  v_payroll record;
  v_sales record;
  v_expenses record;
  v_recruitment record;
  v_risk record;
begin
  select id, month, year into v_payroll_batch
  from public.salary_batches
  order by year desc, month desc
  limit 1;

  if v_payroll_batch.id is not null then
    select
      count(*)::int as employees,
      coalesce(sum(gross_salary), 0)::numeric as gross,
      coalesce(sum(net_salary), 0)::numeric as net,
      (select count(*)::int from public.salary_flags where batch_id = v_payroll_batch.id) as flags
    into v_payroll
    from public.salary_records
    where batch_id = v_payroll_batch.id;
  end if;

  select
    coalesce(sum(sales_value), 0)::numeric as sales_value,
    coalesce(sum(target_value), 0)::numeric as target_value,
    case
      when coalesce(sum(target_value), 0) > 0
        then (sum(sales_value) / sum(target_value) * 100)::numeric
      else 0
    end as achievement_rate
  into v_sales
  from public.sales_records;

  select
    coalesce(sum(claimed_total_amount), 0)::numeric as total_amount,
    coalesce(sum(case when status = 'approved' then claimed_total_amount else 0 end), 0)::numeric as approved_amount,
    count(*)::int as report_count
  into v_expenses
  from public.outstation_expense_requests;

  select
    count(*)::int as total_offers,
    count(*) filter (where status = 'sent')::int as pending_offers,
    count(*) filter (where status = 'accepted')::int as accepted_offers,
    count(*) filter (where status = 'rejected')::int as rejected_offers,
    case
      when count(*) > 0
        then (count(*) filter (where status = 'accepted')::numeric / count(*) * 100)::numeric
      else 0
    end as acceptance_rate
  into v_recruitment
  from public.job_offers;

  select
    (select count(*)::int from public.employees where employment_status = 'active' and hire_date is not null) as active_employees,
    (
      select count(*)::int
      from public.employee_contracts
      where status = 'active'
        and coalesce(contract_renewal_date, contract_end_date) < now() + interval '30 days'
    ) as expiring_contracts,
    (
      select count(*)::int
      from public.employee_probation
      where status = 'active'
        and probation_end_date < now() + interval '14 days'
    ) as probation_endings
  into v_risk;

  v_result = jsonb_build_object(
    'hr', jsonb_build_object(
      'activeEmployees', coalesce(v_risk.active_employees, 0),
      'totalEmployees', (select count(*)::int from public.employees)
    ),
    'payroll', jsonb_build_object(
      'batchLabel', coalesce(v_payroll_batch.month::text || '/' || v_payroll_batch.year::text, '-'),
      'employees', coalesce(v_payroll.employees, 0),
      'gross', coalesce(v_payroll.gross, 0),
      'net', coalesce(v_payroll.net, 0),
      'flags', coalesce(v_payroll.flags, 0)
    ),
    'sales', jsonb_build_object(
      'salesValue', coalesce(v_sales.sales_value, 0),
      'targetValue', coalesce(v_sales.target_value, 0),
      'achievementRate', coalesce(v_sales.achievement_rate, 0)
    ),
    'expenses', jsonb_build_object(
      'approvedAmount', coalesce(v_expenses.approved_amount, 0),
      'totalAmount', coalesce(v_expenses.total_amount, 0),
      'reportCount', coalesce(v_expenses.report_count, 0)
    ),
    'recruitment', jsonb_build_object(
      'totalOffers', coalesce(v_recruitment.total_offers, 0),
      'pendingOffers', coalesce(v_recruitment.pending_offers, 0),
      'acceptedOffers', coalesce(v_recruitment.accepted_offers, 0),
      'rejectedOffers', coalesce(v_recruitment.rejected_offers, 0),
      'acceptanceRate', coalesce(v_recruitment.acceptance_rate, 0)
    ),
    'risk', jsonb_build_object(
      'expiringContracts', coalesce(v_risk.expiring_contracts, 0),
      'probationEndings', coalesce(v_risk.probation_endings, 0)
    )
  );

  return v_result;
end;
$$;


--
-- TOC entry 825 (class 1255 OID 16579)
-- Name: fn_get_employee_directory_paginated(text, bigint, bigint, bigint, bigint, text, integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_employee_directory_paginated(p_search text DEFAULT NULL::text, p_line_id bigint DEFAULT NULL::bigint, p_area_id bigint DEFAULT NULL::bigint, p_department_id bigint DEFAULT NULL::bigint, p_team_id bigint DEFAULT NULL::bigint, p_status text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 50, p_access_scope text DEFAULT 'company'::text, p_access_role text DEFAULT 'Manager'::text, p_access_hr_id text DEFAULT NULL::text) RETURNS TABLE(employees jsonb, total_count bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_offset int;
  v_allowed_hr_ids text[];
begin
  v_offset := (p_page - 1) * p_page_size;

  -- Handle permissions - More comprehensive role handling
  if p_access_scope = 'system' or p_access_role in (
    'Super Admin', 'CEO', 'HR Specialist', 'Finance Manager', 
    'National Sales Manager', 'Product Manager', 'Group Product Manager', 
    'SFE Manager', 'Training Manager', 'Marketing Manager'
  ) then
    v_allowed_hr_ids := null; -- Full or broad visibility
  elsif p_access_role in ('Regional Manager', 'Regional Sales Manager') then
    -- Regional managers see their hierarchy
    select array_agg(hr_id) into v_allowed_hr_ids from public.fn_get_employee_hierarchy(p_access_hr_id);
  else
    -- District Managers and others see themselves and their reports
    v_allowed_hr_ids := array[p_access_hr_id];
  end if;

  return query
  with filtered_employees as (
    select e.*
    from public.employees e
    where
      (p_search is null or 
       e.full_name ilike '%' || p_search || '%' or 
       e.hr_id ilike '%' || p_search || '%' or 
       e.work_email ilike '%' || p_search || '%')
      and (p_line_id is null or e.line_id = p_line_id)
      and (p_area_id is null or e.area_id = p_area_id)
      and (p_department_id is null or e.department_id = p_department_id)
      and (p_team_id is null or e.team_id = p_team_id)
      and (p_status is null or e.employment_status = p_status)
      and (
        v_allowed_hr_ids is null
        or e.hr_id = any(v_allowed_hr_ids)
        or e.manager_hr_id = p_access_hr_id -- Always include direct reports for any manager role
      )
  ),
  total as (
    select count(*) as cnt from filtered_employees
  ),
  paginated as (
    select 
      fe.*,
      c.net_salary, c.social_insurance, c.taxes, c.medical_insurance, c.fuel_allowance, c.extra_cost_of_living, c.gross_salary, c.payment_mode,
      d.name as department_name,
      l.name as line_name,
      a.name as area_name,
      p.title as position_title,
      t.name as team_name,
      m.full_name as manager_name
    from filtered_employees fe
    left join public.employee_compensation c on c.employee_hr_id = fe.hr_id
    left join public.departments d on d.id = fe.department_id
    left join public.lines l on l.id = fe.line_id
    left join public.areas a on a.id = fe.area_id
    left join public.positions p on p.id = fe.position_id
    left join public.teams t on t.id = fe.team_id
    left join public.employees m on m.hr_id = fe.manager_hr_id
    order by fe.full_name asc
    limit p_page_size
    offset v_offset
  )
  -- Ensure we return at least one row even if empty, to avoid PGRST errors or empty results in JS
  select 
    (select coalesce(jsonb_agg(to_jsonb(paginated)), '[]'::jsonb) from paginated),
    coalesce((select cnt from total), 0)::bigint;
end;
$$;


--
-- TOC entry 826 (class 1255 OID 16582)
-- Name: fn_get_employee_hierarchy(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_get_employee_hierarchy(p_root_hr_id text) RETURNS TABLE(hr_id text, depth integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  return query
  with recursive employee_tree as (
    -- Anchor member
    select e.hr_id, 1 as depth
    from public.employees e
    where e.hr_id = p_root_hr_id

    union all

    -- Recursive member
    select e.hr_id, t.depth + 1
    from public.employees e
    inner join employee_tree t on e.manager_hr_id = t.hr_id
    where t.depth < 20 -- Safety limit
  )
  select et.hr_id, et.depth from employee_tree et;
end;
$$;


--
-- TOC entry 827 (class 1255 OID 16583)
-- Name: generate_employee_lifecycle_notifications(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_employee_lifecycle_notifications(p_employee_hr_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  e record;
  d integer;
begin
  select * into e
  from public.employees
  where hr_id = p_employee_hr_id;

  if not found then
    raise exception 'Employee % not found', p_employee_hr_id;
  end if;

  -- Probation: 30/14/7/0 days
  if e.probation_end_date is not null then
    foreach d in array array[30,14,7,0]
    loop
      perform public.create_lifecycle_notification_event(
        'probation',
        e.hr_id,
        e.probation_end_date - d,
        case when d = 0 then 'Probation ends today: ' else 'Probation reminder: ' end || e.full_name,
        jsonb_build_object('days_before', d, 'target_date', e.probation_end_date)
      );
    end loop;
  end if;

  -- Contract renewal: 60/30/7/0 days
  if e.contract_renewal_date is not null then
    foreach d in array array[60,30,7,0]
    loop
      perform public.create_lifecycle_notification_event(
        'contract_renewal',
        e.hr_id,
        e.contract_renewal_date - d,
        case when d = 0 then 'Contract renewal due today: ' else 'Contract renewal reminder: ' end || e.full_name,
        jsonb_build_object('days_before', d, 'target_date', e.contract_renewal_date)
      );
    end loop;
  end if;

  -- Birthday: current year occurrence only for now; yearly scheduler can regenerate annually
  if e.birth_date is not null then
    perform public.create_lifecycle_notification_event(
      'birthday',
      e.hr_id,
      make_date(extract(year from current_date)::int, extract(month from e.birth_date)::int, extract(day from e.birth_date)::int),
      'Birthday reminder: ' || e.full_name,
      jsonb_build_object('birth_date', e.birth_date)
    );
  end if;
end;
$$;


--
-- TOC entry 828 (class 1255 OID 16584)
-- Name: generate_report_it_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_report_it_number() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  year_str text;
  seq_num  bigint;
begin
  year_str := to_char(now(), 'YYYY');
  seq_num  := nextval('report_it_report_number_seq');
  return 'RPT-' || year_str || '-' || lpad(seq_num::text, 5, '0');
end;
$$;


--
-- TOC entry 829 (class 1255 OID 16585)
-- Name: import_marketing_request_atomic(jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_marketing_request_atomic(p_request jsonb, p_products jsonb DEFAULT '[]'::jsonb, p_pharmacies jsonb DEFAULT '[]'::jsonb, p_steps jsonb DEFAULT '[]'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid;
begin
  insert into marketing_requests (
    request_code, requester_hr_id, customer_id, request_type_id, other_request_type,
    request_date, pay_date, roi_duration_months, estimated_cost, expected_roi_value,
    roi_status, notes, status, submitted_at, approved_at, created_by_hr_id, updated_by_hr_id
  )
  select
    r.request_code, r.requester_hr_id, r.customer_id, r.request_type_id, r.other_request_type,
    r.request_date, r.pay_date,
    coalesce(r.roi_duration_months, 1), coalesce(r.estimated_cost, 0), coalesce(r.expected_roi_value, 0),
    coalesce(nullif(r.roi_status, ''), 'not_calculated'), r.notes,
    coalesce(nullif(r.status, ''), 'draft'),
    r.submitted_at, r.approved_at, r.created_by_hr_id, r.updated_by_hr_id
  from jsonb_to_record(p_request) as r(
    request_code text, requester_hr_id text, customer_id uuid, request_type_id bigint, other_request_type text,
    request_date date, pay_date date, roi_duration_months integer, estimated_cost numeric, expected_roi_value numeric,
    roi_status text, notes text, status text, submitted_at timestamptz, approved_at timestamptz,
    created_by_hr_id text, updated_by_hr_id text
  )
  returning id into v_request_id;

  if jsonb_array_length(coalesce(p_products, '[]'::jsonb)) > 0 then
    insert into marketing_request_products (
      request_id, product_id, product_name_snapshot, factory_price_snapshot, forecast_quantity, value_share
    )
    select
      v_request_id, p.product_id, p.product_name_snapshot,
      coalesce(p.factory_price_snapshot, 0), coalesce(p.forecast_quantity, 0), coalesce(p.value_share, 0)
    from jsonb_to_recordset(p_products) as p(
      product_id bigint, product_name_snapshot text, factory_price_snapshot numeric,
      forecast_quantity numeric, value_share numeric
    );
  end if;

  if jsonb_array_length(coalesce(p_pharmacies, '[]'::jsonb)) > 0 then
    insert into marketing_request_pharmacies (
      request_id, distributor_code_id, tracking_status
    )
    select
      v_request_id, ph.distributor_code_id,
      coalesce(nullif(ph.tracking_status, ''), 'pending_validation')
    from jsonb_to_recordset(p_pharmacies) as ph(
      distributor_code_id uuid, tracking_status text
    );
  end if;

  if jsonb_array_length(coalesce(p_steps, '[]'::jsonb)) > 0 then
    insert into marketing_request_approval_steps (
      request_id, workflow_step_id, sequence, step_code, step_name, assigned_role,
      status, decision_at, decision_by_hr_id, decision_note
    )
    select
      v_request_id, s.workflow_step_id, s.sequence, s.step_code, s.step_name, s.assigned_role,
      coalesce(nullif(s.status, ''), 'pending'), s.decision_at, s.decision_by_hr_id, s.decision_note
    from jsonb_to_recordset(p_steps) as s(
      workflow_step_id bigint, sequence integer, step_code text, step_name text, assigned_role text,
      status text, decision_at timestamptz, decision_by_hr_id text, decision_note text
    );
  end if;

  return v_request_id;
end;
$$;


