    notes text,
    sick_attachment_bucket text,
    sick_attachment_object_path text,
    sick_attachment_original_name text,
    sick_attachment_content_type text,
    sick_attachment_size_bytes bigint,
    sick_attachment_uploaded_at timestamp with time zone,
    hr_decision text,
    hr_decision_by_hr_id text,
    hr_decision_at timestamp with time zone,
    hr_decision_comment text,
    compensatory_event_name text,
    compensatory_event_date date,
    compensatory_event_location text,
    compensatory_manager_1 text,
    compensatory_manager_2 text,
    compensatory_attachment_bucket text,
    compensatory_attachment_object_path text,
    compensatory_attachment_original_name text,
    compensatory_attachment_content_type text,
    compensatory_attachment_size_bytes bigint,
    compensatory_attachment_uploaded_at timestamp with time zone,
    paid_duration_days numeric(8,2) DEFAULT 0 NOT NULL,
    unpaid_duration_days numeric(8,2) DEFAULT 0 NOT NULL,
    weekly_off_policy_snapshot jsonb,
    employee_note text,
    CONSTRAINT v2_vacation_requests_compensatory_required_check CHECK (((vacation_type <> 'compensatory'::text) OR ((btrim(COALESCE(compensatory_event_name, ''::text)) <> ''::text) AND (compensatory_event_date IS NOT NULL) AND (btrim(COALESCE(compensatory_event_location, ''::text)) <> ''::text) AND (btrim(COALESCE(compensatory_manager_1, ''::text)) <> ''::text) AND (compensatory_attachment_object_path IS NOT NULL)))),
    CONSTRAINT v2_vacation_requests_date_order CHECK ((end_date >= start_date)),
    CONSTRAINT v2_vacation_requests_day_part_check CHECK ((day_part = ANY (ARRAY['full_day'::text, 'am_only'::text, 'pm_only'::text]))),
    CONSTRAINT v2_vacation_requests_duration_days_check CHECK ((duration_days > (0)::numeric)),
    CONSTRAINT v2_vacation_requests_hr_decision_check CHECK (((hr_decision IS NULL) OR (hr_decision = ANY (ARRAY['approved'::text, 'rejected'::text])))),
    CONSTRAINT v2_vacation_requests_manager_decision_check CHECK (((manager_decision IS NULL) OR (manager_decision = ANY (ARRAY['approved'::text, 'rejected'::text])))),
    CONSTRAINT v2_vacation_requests_paid_unpaid_duration_check CHECK (((paid_duration_days >= (0)::numeric) AND (unpaid_duration_days >= (0)::numeric) AND (round((paid_duration_days + unpaid_duration_days), 2) = round((duration_days)::numeric, 2)))),
    CONSTRAINT v2_vacation_requests_payment_status_check CHECK ((payment_status = ANY (ARRAY['paid'::text, 'partial'::text, 'unpaid'::text]))),
    CONSTRAINT v2_vacation_requests_status_check CHECK ((status = ANY (ARRAY['needs_assignment'::text, 'pending_manager'::text, 'pending_hr'::text, 'approved'::text, 'rejected'::text, 'returned'::text]))),
    CONSTRAINT v2_vacation_requests_unpaid_reason_check CHECK (((unpaid_reason IS NULL) OR (unpaid_reason = ANY (ARRAY['first_six_months'::text, 'insufficient_balance'::text, 'missing_hire_date'::text])))),
    CONSTRAINT v2_vacation_requests_vacation_type_check CHECK ((vacation_type = ANY (ARRAY['annual'::text, 'emergency'::text, 'sick'::text, 'other'::text, 'compensatory'::text])))
);


--
-- TOC entry 831 (class 1255 OID 16610)
-- Name: phx_apply_vacation_paid_approval(uuid, text, text, text, text, text, timestamp with time zone, numeric, date, date, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_apply_vacation_paid_approval(p_request_id uuid, p_expected_status text, p_next_status text, p_step text, p_decision_by_hr_id text, p_decision_comment text, p_now timestamp with time zone, p_entitlement_days numeric, p_period_start date, p_period_end date, p_duration_days numeric, p_vacation_type text) RETURNS public.v2_vacation_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee_hr_id text;
  v_used numeric;
  v_balance_before numeric;
  v_paid numeric;
  v_unpaid numeric;
  v_balance_after numeric;
  v_payment_status text;
  v_unpaid_reason text;
  v_row public.v2_vacation_requests;
begin
  -- Lock the target request row and enforce the status compare-and-swap. Different
  -- requests never contend on this row lock; it only guards this request's transition.
  select * into v_row from public.v2_vacation_requests where id = p_request_id for update;
  if not found then
    raise exception 'Vacation request was not found.' using errcode = 'P0002';
  end if;
  if v_row.status is distinct from p_expected_status then
    raise exception 'Vacation request was updated by another user. Refresh and try again.'
      using errcode = '40001';
  end if;
  v_employee_hr_id := v_row.employee_hr_id;

  -- Serialize ALL paid-balance decisions for this employee for the rest of the
  -- transaction, so two concurrent approvals in the same period cannot both consume
  -- the same remaining entitlement. Released automatically at commit/rollback.
  perform pg_advisory_xact_lock(hashtext(lower(v_employee_hr_id)));

  -- Authoritative used-paid-days in the balance period. Mirrors approvedPaidDaysInPeriod:
  -- annual and emergency share one period bucket; other types match exactly. paid_duration_days
  -- is NOT NULL, so summing it is equivalent to the JS branch.
  select coalesce(sum(paid_duration_days), 0) into v_used
  from public.v2_vacation_requests
  where lower(employee_hr_id) = lower(v_employee_hr_id)
    and status = 'approved'
    and id <> p_request_id
    and start_date >= p_period_start
    and start_date <  p_period_end
    and (
      (p_vacation_type in ('annual', 'emergency') and vacation_type in ('annual', 'emergency'))
      or (p_vacation_type not in ('annual', 'emergency') and vacation_type = p_vacation_type)
    );

  -- Paid/unpaid split (mirrors splitVacationPayment; roundDays = round to 2 decimals).
  v_used := round(v_used, 2);
  v_balance_before := round(greatest(0, p_entitlement_days - v_used), 2);
  v_paid := round(least(p_duration_days, greatest(0, v_balance_before)), 2);
  v_unpaid := round(greatest(0, p_duration_days - v_paid), 2);
  v_balance_after := round(greatest(0, v_balance_before - v_paid), 2);
  if v_unpaid > 0 and v_paid > 0 then
    v_payment_status := 'partial';
  elsif v_unpaid > 0 then
    v_payment_status := 'unpaid';
  else
    v_payment_status := 'paid';
  end if;
  v_unpaid_reason := case when v_unpaid > 0 then 'insufficient_balance' else null end;

  update public.v2_vacation_requests set
    status = p_next_status,
    updated_at = p_now,
    payment_status = v_payment_status,
    paid_duration_days = v_paid,
    unpaid_duration_days = v_unpaid,
    unpaid_reason = v_unpaid_reason,
    entitlement_days = round(p_entitlement_days, 2),
    used_paid_days = v_used,
    balance_before_days = v_balance_before,
    balance_after_days = v_balance_after,
    period_start = p_period_start,
    period_end = p_period_end,
    hr_decision = case when p_step = 'hr' then 'approved' else hr_decision end,
    hr_decision_by_hr_id = case when p_step = 'hr' then p_decision_by_hr_id else hr_decision_by_hr_id end,
    hr_decision_at = case when p_step = 'hr' then p_now else hr_decision_at end,
    hr_decision_comment = case when p_step = 'hr' then p_decision_comment else hr_decision_comment end,
    manager_decision = case when p_step <> 'hr' then 'approved' else manager_decision end,
    manager_decision_by_hr_id = case when p_step <> 'hr' then p_decision_by_hr_id else manager_decision_by_hr_id end,
    manager_decision_at = case when p_step <> 'hr' then p_now else manager_decision_at end,
    manager_decision_comment = case when p_step <> 'hr' then p_decision_comment else manager_decision_comment end
  where id = p_request_id
  returning * into v_row;

  return v_row;
end;
$$;


