--
-- TOC entry 839 (class 1255 OID 16620)
-- Name: phx_coaching_zone(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_coaching_zone(p_percent numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when p_percent < 50 then 'critical_red'
    when p_percent <= 65 then 'red_zone'
    when p_percent <= 80 then 'yellow_zone'
    when p_percent <= 90 then 'green_zone'
    else 'excellence_zone'
  end;
$$;


--
-- TOC entry 840 (class 1255 OID 16621)
-- Name: phx_create_salary_batch(integer, integer, text, text, jsonb, jsonb, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_create_salary_batch(p_month integer, p_year integer, p_file_name text, p_uploaded_by text, p_records jsonb, p_flags jsonb, p_created_at timestamp with time zone, p_file_content_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_records jsonb := coalesce(p_records, '[]'::jsonb);
  v_flags jsonb := coalesce(p_flags, '[]'::jsonb);
begin
  if p_month < 1 or p_month > 12 then
    raise exception 'Payroll month must be between 1 and 12.' using errcode = '22023';
  end if;

  if p_year < 2000 or p_year > 2100 then
    raise exception 'Payroll year must be between 2000 and 2100.' using errcode = '22023';
  end if;

  if jsonb_typeof(v_records) <> 'array' then
    raise exception 'Payroll upload records must be a JSON array.' using errcode = '22023';
  end if;

  if jsonb_typeof(v_flags) <> 'array' then
    raise exception 'Payroll upload flags must be a JSON array.' using errcode = '22023';
  end if;

  if jsonb_array_length(v_records) = 0 then
    raise exception 'Payroll upload records must include at least one salary record.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(v_records) as record(value)
    where jsonb_typeof(record.value) <> 'object'
  ) then
    raise exception 'Payroll upload records must contain JSON objects.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(v_flags) as flag(value)
    where jsonb_typeof(flag.value) <> 'object'
  ) then
    raise exception 'Payroll upload flags must contain JSON objects.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_records) as r(hr_id text)
    where nullif(trim(coalesce(r.hr_id, '')), '') is null
  ) then
    raise exception 'Payroll upload records must include HR IDs.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_records) as r(payment_mode text)
    where coalesce(r.payment_mode, 'two_parts') not in ('one_part', 'two_parts')
  ) then
    raise exception 'Payroll upload payment_mode must be one_part or two_parts.' using errcode = '22023';
  end if;

  begin
    insert into public.salary_batches (
      file_name,
      month,
      year,
      status,
      uploaded_by,
      created_at,
      updated_at,
      file_content_hash
    )
    values (
      p_file_name,
      p_month,
      p_year,
      'uploaded',
      p_uploaded_by,
      p_created_at,
      p_created_at,
      p_file_content_hash
    )
    returning *
    into v_batch;
  exception
    when unique_violation then
      if sqlerrm ilike '%salary_batches_period_hash_uniq%' then
        raise exception 'This exact file has already been uploaded for payroll period %/%.', p_month, p_year using errcode = '23505';
      else
        raise exception 'Payroll period %/% already has a batch.', p_month, p_year using errcode = '23505';
      end if;
  end;

  insert into public.salary_records (
    area,
    base_salary,
    batch_id,
    bonus,
    crm,
    employment_income_tax,
    expenses,
    extra_cost_of_living,
    finger_print,
    first_part,
    fuel_allowance,
    full_name,
    governmental_deductions,
    gross_salary,
    hire_date,
    hr_id,
    incentive,
    job_title,
    line,
    loans,
    medical_insurance,
    month_salary,
    name_ar,
    net_salary,
    other_additions,
    other_deductions,
    overtime,
    comment,
    payment_mode,
    second_part,
    social_insurance,
    total_additions,
    total_deductions,
    unpaid_vacations
  )
  select
    r.area,
    coalesce(r.base_salary, 0),
    v_batch.id,
    r.bonus,
    r.crm,
    r.employment_income_tax,
    r.expenses,
    r.extra_cost_of_living,
    r.finger_print,
    r.first_part,
    r.fuel_allowance,
    r.full_name,
    r.governmental_deductions,
    r.gross_salary,
    r.hire_date,
    r.hr_id,
    r.incentive,
    r.job_title,
    r.line,
    r.loans,
    r.medical_insurance,
    r.month_salary,
    r.name_ar,
    r.net_salary,
    r.other_additions,
    r.other_deductions,
    r.overtime,
    r.comment,
    coalesce(r.payment_mode, 'two_parts'),
    r.second_part,
    r.social_insurance,
    r.total_additions,
    r.total_deductions,
    r.unpaid_vacations
  from jsonb_to_recordset(v_records) as r(
    area text,
    base_salary numeric,
    bonus numeric,
    crm numeric,
    employment_income_tax numeric,
    expenses numeric,
    extra_cost_of_living numeric,
    finger_print numeric,
    first_part numeric,
    fuel_allowance numeric,
    full_name text,
    governmental_deductions numeric,
    gross_salary numeric,
    hire_date date,
    hr_id text,
    incentive numeric,
    job_title text,
    line text,
    loans numeric,
    medical_insurance numeric,
    month_salary numeric,
    name_ar text,
    net_salary numeric,
    other_additions numeric,
    other_deductions numeric,
    overtime numeric,
    comment text,
    payment_mode text,
    second_part numeric,
    social_insurance numeric,
    total_additions numeric,
    total_deductions numeric,
    unpaid_vacations numeric
  );

  insert into public.salary_flags (
    batch_id,
    flag_type,
    hr_id,
    message,
    severity
  )
  select
    v_batch.id,
    f.flag_type,
    f.hr_id,
    f.message,
    coalesce(f.severity, 'warning')
  from jsonb_to_recordset(v_flags) as f(
    flag_type text,
    hr_id text,
    message text,
    severity text
  );

  return to_jsonb(v_batch);
end;
$$;


--
-- TOC entry 841 (class 1255 OID 16624)
-- Name: phx_customer_directory(text[], text[], text[], text[], text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_customer_directory(p_region_codes text[] DEFAULT NULL::text[], p_area_codes text[] DEFAULT NULL::text[], p_brick_codes text[] DEFAULT NULL::text[], p_distributor_codes text[] DEFAULT NULL::text[], p_from_period text DEFAULT NULL::text, p_to_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT '{}'::text[]) RETURNS TABLE(client_code text, client_name text, client_address text, distributor_code text, brick_id text, area_code text, region_code text, total_units numeric, total_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    SET work_mem TO '128MB'
    AS $$
  with filtered as materialized (
    select
      c.client_code,
      c.client_name,
      c.client_address,
      c.distributor_code,
      c.brick_id,
      c.area_code,
      c.region_code,
      c.latest_row_created_at,
      c.total_qty,
      c.effective_units * coalesce(p.factory_price, 0) as line_value
    from public.source_of_sales_customer_directory_rollup c
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = c.product_code
    where (p_distributor_codes is null or cardinality(p_distributor_codes) = 0 or c.distributor_code = any(p_distributor_codes))
      and (p_region_codes is null or cardinality(p_region_codes) = 0 or c.region_code = any(p_region_codes))
      and (p_area_codes is null or cardinality(p_area_codes) = 0 or c.area_code = any(p_area_codes))
      and (p_brick_codes is null or cardinality(p_brick_codes) = 0 or c.brick_id = any(p_brick_codes))
      and (p_from_period is null or c.period >= p_from_period)
      and (p_to_period is null or c.period <= p_to_period)
      and upper(btrim(coalesce(c.product_code, ''))) <> all (
        select upper(btrim(x)) from unnest(coalesce(p_exclude_codes, '{}'::text[])) as x
      )
  ),
  latest as (
    select distinct on (client_code, distributor_code)
      client_code,
      distributor_code,
      client_name,
      client_address,
      brick_id,
      area_code,
      region_code
    from filtered
    order by client_code, distributor_code, latest_row_created_at desc
  ),
  agg as (
    select
      client_code,
      distributor_code,
      sum(total_qty) as total_units,
      sum(line_value) as total_value
    from filtered
    group by client_code, distributor_code
  )
  select
    a.client_code,
    l.client_name,
    l.client_address,
    a.distributor_code,
    l.brick_id,
    l.area_code,
    l.region_code,
    a.total_units,
    a.total_value
  from agg a
  join latest l using (client_code, distributor_code);
$$;


--
-- TOC entry 842 (class 1255 OID 16625)
-- Name: phx_customer_directory_json(text[], text[], text[], text[], text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_customer_directory_json(p_region_codes text[] DEFAULT NULL::text[], p_area_codes text[] DEFAULT NULL::text[], p_brick_codes text[] DEFAULT NULL::text[], p_distributor_codes text[] DEFAULT NULL::text[], p_from_period text DEFAULT NULL::text, p_to_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(row)), '[]'::jsonb)
  from (
    select *
    from public.phx_customer_directory(
      p_region_codes,
      p_area_codes,
      p_brick_codes,
      p_distributor_codes,
      p_from_period,
      p_to_period,
      p_exclude_codes
    )
  ) row;
$$;


--
-- TOC entry 843 (class 1255 OID 16626)
-- Name: phx_customer_sales(text, text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_customer_sales(p_distributor_code text, p_client_code text, p_from_period text DEFAULT NULL::text, p_to_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT '{}'::text[]) RETURNS TABLE(invoice_period text, product_code text, product_name text, official_line text, brick_id text, area_code text, region_code text, client_name text, client_address text, qty numeric, line_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    r.invoice_period, r.product_code, r.product_name, r.official_line, r.brick_id,
    r.area_code, r.region_code, r.client_name, r.client_address, r.qty,
    r.qty * (1 - coalesce(r.discount, 0)) * coalesce(p.factory_price, 0) as line_value
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b on b.id = r.batch_id
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
  where b.status = 'validated'
    and r.distributor_code = p_distributor_code
    and r.client_code = p_client_code
    and (p_from_period is null or r.invoice_period >= p_from_period)
    and (p_to_period is null or r.invoice_period <= p_to_period)
    and upper(btrim(coalesce(r.product_code, ''))) <> all (
      select upper(btrim(x)) from unnest(coalesce(p_exclude_codes, '{}'::text[])) as x
    )
  order by r.invoice_period, r.product_name;
$$;


--
-- TOC entry 844 (class 1255 OID 16627)
-- Name: phx_decide_marketing_request_step(uuid, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_decide_marketing_request_step(p_step_id uuid, p_request_id uuid, p_decision text, p_decided_by text, p_decision_note text, p_decided_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_terminal_step_status text;
  v_step                 marketing_request_approval_steps%ROWTYPE;
  v_request              marketing_requests%ROWTYPE;
  v_next_step            marketing_request_approval_steps%ROWTYPE;
  v_has_next             boolean := false;
  v_terminal_status      text;
  v_is_execution         boolean := false;
BEGIN
  -- Map decision → step terminal status
  v_terminal_step_status := CASE p_decision
    WHEN 'approve' THEN 'approved'
    WHEN 'reject'  THEN 'rejected'
    WHEN 'return'  THEN 'returned'
  END;

  IF v_terminal_step_status IS NULL THEN
    RAISE EXCEPTION 'Invalid marketing request decision: %', p_decision;
  END IF;

  -- 1. Stamp the current step with optimistic-lock (status must still be 'current').
  UPDATE marketing_request_approval_steps SET
    decision_at       = p_decided_at,
    decision_by_hr_id = p_decided_by,
    decision_note     = NULLIF(btrim(COALESCE(p_decision_note, '')), ''),
    status            = v_terminal_step_status,
    updated_at        = p_decided_at
  WHERE id     = p_step_id
    AND status = 'current'
  RETURNING * INTO v_step;

  IF NOT FOUND THEN
    -- Signals a concurrent decision; caller maps this to a 409 conflict.
    RAISE EXCEPTION 'marketing_step_already_decided: step % was no longer current', p_step_id;
  END IF;

  -- ── Branch A: reject or return ───────────────────────────────────────────
  IF p_decision IN ('reject', 'return') THEN
    UPDATE marketing_requests SET
      rejected_at            = CASE WHEN p_decision = 'reject' THEN p_decided_at ELSE NULL END,
      returned_at            = CASE WHEN p_decision = 'return' THEN p_decided_at ELSE NULL END,
      returned_step_sequence = CASE WHEN p_decision = 'return' THEN v_step.sequence ELSE NULL END,
      status                 = CASE WHEN p_decision = 'reject' THEN 'rejected'::text ELSE 'returned'::text END,
      updated_at             = p_decided_at,
      updated_by_hr_id       = p_decided_by
    WHERE id = p_request_id
    RETURNING * INTO v_request;

    RETURN jsonb_build_object(
      'branch',      p_decision,
      'step',        to_jsonb(v_step),
      'request',     to_jsonb(v_request),
      'nextStep',    NULL,
      'isExecution', false
    );
  END IF;

  -- ── Branch B or C: approve ───────────────────────────────────────────────
  -- Try to advance the next pending non-CC step atomically.
  UPDATE marketing_request_approval_steps SET
    status     = 'current',
    updated_at = p_decided_at
  WHERE id = (
    SELECT id
    FROM   marketing_request_approval_steps
    WHERE  request_id = p_request_id
      AND  status     = 'pending'
      AND  is_cc      = false
      AND  sequence   > v_step.sequence
    ORDER  BY sequence
    LIMIT  1
  )
  AND status = 'pending'   -- second guard against a concurrent write on the same row
  RETURNING * INTO v_next_step;

  v_has_next := FOUND;

  -- ── Branch B: next approver exists ───────────────────────────────────────
  IF v_has_next THEN
    -- marketing_requests stays 'pending_approval'; just return the current row.
    SELECT * INTO v_request FROM marketing_requests WHERE id = p_request_id;

    RETURN jsonb_build_object(
      'branch',      'approve_next',
      'step',        to_jsonb(v_step),
      'request',     to_jsonb(v_request),
      'nextStep',    to_jsonb(v_next_step),
      'isExecution', false
    );
  END IF;

  -- ── Branch C: final approval ──────────────────────────────────────────────
  v_terminal_status := COALESCE(v_step.terminal_status, 'approved');
  v_is_execution    := (v_terminal_status = 'active');

  UPDATE marketing_requests SET
    approved_at      = p_decided_at,
    executed_at      = CASE WHEN v_is_execution THEN p_decided_at ELSE NULL END,
    status           = v_terminal_status,
    updated_at       = p_decided_at,
    updated_by_hr_id = p_decided_by
  WHERE id = p_request_id
  RETURNING * INTO v_request;

  -- Finance-execution steps also stamp executed_at on the step row.
  IF v_is_execution THEN
    UPDATE marketing_request_approval_steps SET
      executed_at = p_decided_at,
      updated_at  = p_decided_at
    WHERE id = p_step_id
    RETURNING * INTO v_step;
  END IF;

  RETURN jsonb_build_object(
    'branch',      'approve_final',
    'step',        to_jsonb(v_step),
    'request',     to_jsonb(v_request),
    'nextStep',    NULL,
    'isExecution', v_is_execution
  );
END;
$$;


--
-- TOC entry 845 (class 1255 OID 16628)
-- Name: phx_delete_salary_batch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_delete_salary_batch(p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_deleted_flags integer := 0;
  v_deleted_records integer := 0;
begin
  if p_batch_id is null then
    raise exception 'Payroll upload id is required.' using errcode = '22023';
  end if;

  select *
  into v_batch
  from public.salary_batches
  where id = p_batch_id
  for update;

  if not found then
    raise exception 'Payroll upload not found.' using errcode = 'P0002';
  end if;

  perform set_config('request.phx_allow_salary_batch_delete', 'on', true);

  delete from public.salary_flags
  where batch_id = p_batch_id;
  get diagnostics v_deleted_flags = row_count;

  delete from public.salary_records
  where batch_id = p_batch_id;
  get diagnostics v_deleted_records = row_count;

  delete from public.salary_batches
  where id = p_batch_id;

  return jsonb_build_object(
    'id', v_batch.id,
    'month', v_batch.month,
    'year', v_batch.year,
    'status', v_batch.status,
    'file_name', v_batch.file_name,
    'records_deleted', v_deleted_records,
    'flags_deleted', v_deleted_flags
  );
end;
$$;


