CREATE FUNCTION public.phx_exec_sos_trend(p_periods text[] DEFAULT '{}'::text[], p_lines text[] DEFAULT '{}'::text[], p_distributors text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[], p_areas text[] DEFAULT '{}'::text[], p_products text[] DEFAULT '{}'::text[], p_exclude_codes text[] DEFAULT '{}'::text[]) RETURNS TABLE(period text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
