    sum(f.total_qty) as units,
    sum(case when f.is_direct
             then f.direct_value
             else f.effective_units * coalesce(p.factory_price, 0) end) as value
  from public.source_of_sales_fact_rollup f
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  where (cardinality(p_periods) = 0 or f.period = any (p_periods))
    and (
      cardinality(p_lines) = 0
      or lower(btrim(coalesce(f.official_line, ''))) in (select lower(btrim(x)) from unnest(p_lines) as x)
    )
    and (
      cardinality(p_distributors) = 0
      or upper(btrim(coalesce(f.distributor_code, ''))) in (select upper(btrim(x)) from unnest(p_distributors) as x)
    )
    and (
      cardinality(p_regions) = 0
      or upper(btrim(coalesce(f.region_code, ''))) in (select upper(btrim(x)) from unnest(p_regions) as x)
    )
    and (
      cardinality(p_areas) = 0
      or upper(btrim(coalesce(nullif(f.area_code, ''), 'DIRECT'))) in (select upper(btrim(x)) from unnest(p_areas) as x)
    )
    and (
      cardinality(p_products) = 0
      or upper(btrim(coalesce(f.product_code, ''))) in (select upper(btrim(x)) from unnest(p_products) as x)
    )
    and (
      cardinality(p_exclude_codes) = 0
      or upper(btrim(coalesce(f.product_code, ''))) <> all (select upper(btrim(x)) from unnest(p_exclude_codes) as x)
    )
  group by f.period;
$$;


--
-- TOC entry 854 (class 1255 OID 16637)
-- Name: phx_finalize_monthly_deductions(text, integer, integer, text, integer, integer, numeric, numeric, jsonb, text, jsonb, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_finalize_monthly_deductions(p_month_key text, p_month integer, p_year integer, p_finalized_by text, p_candidate_count integer, p_employee_count integer, p_total_days numeric, p_total_amount numeric, p_source_counts jsonb, p_notes text, p_lines jsonb, p_decision_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_summary_id uuid;
  v_result     jsonb;
BEGIN
  INSERT INTO deduction_monthly_summaries (
    month_key, month, year, finalized_by,
    candidate_count, employee_count, total_days, total_amount,
    source_counts, notes
  ) VALUES (
    p_month_key, p_month, p_year, p_finalized_by,
    p_candidate_count, p_employee_count, p_total_days, p_total_amount,
    COALESCE(p_source_counts, '{}'::jsonb),
    NULLIF(btrim(COALESCE(p_notes, '')), '')
  )
  RETURNING id INTO v_summary_id;

  INSERT INTO deduction_monthly_summary_lines (
    summary_id, candidate_id, decision_id,
    employee_code, employee_hr_id_compact, employee_name,
    month_key, source_module, deduction_type, payroll_column, deduction_unit,
    original_deduction_value, applied_deduction_value, applied_amount,
    dates, reason, hr_note
  )
  SELECT
    v_summary_id,
    (line->>'candidate_id')::uuid,
    (line->>'decision_id')::uuid,
    line->>'employee_code',
    line->>'employee_hr_id_compact',
    NULLIF(line->>'employee_name', ''),
    line->>'month_key',
    line->>'source_module',
    line->>'deduction_type',
    line->>'payroll_column',
    line->>'deduction_unit',
    (line->>'original_deduction_value')::numeric,
    (line->>'applied_deduction_value')::numeric,
    (line->>'applied_amount')::numeric,
    COALESCE(line->'dates', '[]'::jsonb),
    NULLIF(line->>'reason',  ''),
    NULLIF(line->>'hr_note', '')
  FROM jsonb_array_elements(p_lines) AS line;

  IF array_length(p_decision_ids, 1) > 0 THEN
    UPDATE deduction_decisions SET
      finalized_summary_id   = v_summary_id,
      payroll_handoff_status = 'Pending integration',
      updated_at             = now()
    WHERE id = ANY(p_decision_ids);
  END IF;

  SELECT jsonb_build_object(
    'id',              id,
    'month_key',       month_key,
    'month',           month,
    'year',            year,
    'status',          status,
    'finalized_by',    finalized_by,
    'finalized_at',    finalized_at,
    'candidate_count', candidate_count,
    'employee_count',  employee_count,
    'total_days',      total_days,
    'total_amount',    total_amount,
    'source_counts',   source_counts,
    'notes',           notes,
    'created_at',      created_at
  ) INTO v_result
  FROM deduction_monthly_summaries
  WHERE id = v_summary_id;

  RETURN v_result;
END;
$$;


--
-- TOC entry 855 (class 1255 OID 16638)
-- Name: phx_finalize_sos_batch(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_finalize_sos_batch(p_batch_id uuid, p_distributor_code text, p_period text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '120s'
    AS $$
declare
  v_superseded jsonb;
  v_raw_count bigint;
  v_rollup_count bigint;
begin
  if not pg_try_advisory_xact_lock(hashtextextended(p_distributor_code || ':' || p_period, 0)) then
    raise exception 'Another upload for % / % is finalizing right now -- retry in a few seconds.', p_distributor_code, p_period
      using errcode = '55P03';
  end if;

  -- Capture what we're about to supersede so the caller can audit-log it (same shape
  -- the old supersedeExistingSalesBatches() TS helper captured before deleting).
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'fileName', file_name,
    'distributorCode', distributor_code,
    'period', period,
    'status', status
  )), '[]'::jsonb)
  into v_superseded
  from public.source_of_sales_import_batches
  where distributor_code = p_distributor_code
    and period = p_period
    and id <> p_batch_id;

  delete from public.source_of_sales_import_batches
  where distributor_code = p_distributor_code
    and period = p_period
    and id <> p_batch_id;

  update public.source_of_sales_import_batches
  set status = 'validated', blocking_reasons = '{}'
  where id = p_batch_id;

  if not found then
    raise exception 'Batch % not found while finalizing.', p_batch_id;
  end if;

  perform public.phx_refresh_sos_fact_rollup(p_batch_id);
  perform public.phx_refresh_sos_customer_directory_rollup(p_batch_id);
  perform public.phx_refresh_marketing_roi_facts(p_batch_id);

  -- Self-check: zero silent row loss between raw rows and the fact-rollup grain.
  -- A checked invariant on every single upload, not an assumption.
  select count(*) into v_raw_count
  from public.source_of_sales_import_rows
  where batch_id = p_batch_id;

  select coalesce(sum(row_count), 0) into v_rollup_count
  from public.source_of_sales_fact_rollup
  where batch_id = p_batch_id;

  if v_raw_count <> v_rollup_count then
    raise exception 'Reconciliation failed for batch %: % raw rows but % rolled up -- aborting.', p_batch_id, v_raw_count, v_rollup_count;
  end if;

  return jsonb_build_object('supersededBatches', v_superseded, 'rowCount', v_raw_count);
end;
$$;


--
-- TOC entry 856 (class 1255 OID 16639)
-- Name: phx_import_approved_expenses_to_payroll(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_import_approved_expenses_to_payroll(p_month integer, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_imported_by text := coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''), 'service_role');
  v_imported_employees integer := 0;
  v_imported_total numeric := 0;
  v_locked_expenses integer := 0;
  v_matched_employees text[] := '{}'::text[];
begin
  select *
  into v_batch
  from public.salary_batches
  where month = p_month
    and year = p_year
  order by created_at desc, id desc
  limit 1
  for update;

  if not found then
    return jsonb_build_object(
      'imported_employees', 0,
      'imported_total', 0,
      'locked_expenses', 0,
      'matched_employees', '[]'::jsonb,
      'target_batch_id', null,
      'target_batch_month', null,
      'target_batch_year', null
    );
  end if;

  if v_batch.status not in ('part1_paid', 'adjustments_open', 'part2_ready', 'under_review', 'rejected') then
    raise exception 'Payroll batch cannot import expenses before Part 1 is paid or while status is %.', v_batch.status using errcode = 'P0001';
  end if;

  with approved_totals as (
    select
      lower(hr_id) as normalized_hr_id,
      min(hr_id) as hr_id,
      sum(total)::numeric(20,2) as approved_expense
    from public.payroll_expenses
    where hr_approved = true
      and approved_at is not null
      and approved_by is not null
      and payout_month = p_month
      and payout_year = p_year
      and hr_id is not null
      and trim(hr_id) <> ''
    group by lower(hr_id)
  ),
  matched_totals as (
    select
      sr.hr_id,
      at.approved_expense
    from public.salary_records sr
    join approved_totals at
      on lower(sr.hr_id) = at.normalized_hr_id
    where sr.batch_id = v_batch.id
  ),
  updated_rows as (
    update public.salary_records sr
    set expenses = coalesce(at.approved_expense, 0),
        total_additions = coalesce(sr.total_additions, 0) - coalesce(sr.expenses, 0) + coalesce(at.approved_expense, 0),
        second_part = coalesce(sr.second_part, 0) - coalesce(sr.expenses, 0) + coalesce(at.approved_expense, 0),
        month_salary = coalesce(sr.month_salary, coalesce(sr.first_part, 0) + coalesce(sr.second_part, 0)) - coalesce(sr.expenses, 0) + coalesce(at.approved_expense, 0)
    from (
      select
        sr2.id,
        at2.approved_expense
      from public.salary_records sr2
      left join approved_totals at2
        on lower(sr2.hr_id) = at2.normalized_hr_id
      where sr2.batch_id = v_batch.id
    ) at
    where sr.id = at.id
      and (
        coalesce(sr.expenses, 0) is distinct from coalesce(at.approved_expense, 0)
        or coalesce(sr.second_part, 0) is distinct from coalesce(sr.second_part, 0) - coalesce(sr.expenses, 0) + coalesce(at.approved_expense, 0)
      )
    returning sr.id
  ),
  marked_expenses as (
    update public.payroll_expenses pe
    set
      imported_payroll_batch_id = v_batch.id,
      imported_to_payroll_at = now(),
      imported_to_payroll_by = v_imported_by
    where pe.hr_approved = true
      and pe.approved_at is not null
      and pe.approved_by is not null
      and pe.payout_month = p_month
      and pe.payout_year = p_year
      and pe.hr_id is not null
      and trim(pe.hr_id) <> ''
      and exists (
        select 1
        from matched_totals mt
        where lower(mt.hr_id) = lower(pe.hr_id)
      )
    returning pe.id
  )
  select
    count(*)::integer,
    coalesce(sum(approved_expense), 0)::numeric,
    (select count(*)::integer from marked_expenses),
    coalesce(array_agg(hr_id order by hr_id), '{}'::text[])
  into
    v_imported_employees,
    v_imported_total,
    v_locked_expenses,
    v_matched_employees
  from matched_totals;

  return jsonb_build_object(
    'imported_employees', v_imported_employees,
    'imported_total', v_imported_total,
    'locked_expenses', v_locked_expenses,
    'matched_employees', to_jsonb(v_matched_employees),
    'target_batch_id', v_batch.id,
    'target_batch_month', v_batch.month,
    'target_batch_year', v_batch.year
  );
end;
$$;


--
-- TOC entry 857 (class 1255 OID 16640)
-- Name: phx_import_deductions_governance_to_payroll(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_import_deductions_governance_to_payroll(p_summary_id uuid, p_import_job_id uuid DEFAULT gen_random_uuid(), p_actor_login_id text DEFAULT 'system'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_summary public.deduction_monthly_summaries%rowtype;
  v_batch public.salary_batches%rowtype;
  v_existing_job public.deduction_payroll_import_jobs%rowtype;
  v_imported_employees integer := 0;
  v_imported_total numeric := 0;
  v_matched_employees jsonb := '[]'::jsonb;
  v_unmatched_employees jsonb := '[]'::jsonb;
begin
  if p_summary_id is null then
    raise exception 'A finalized deductions summary is required.' using errcode = 'P0001';
  end if;

  select *
  into v_summary
  from public.deduction_monthly_summaries
  where id = p_summary_id
  for update;

  if not found then
    raise exception 'Deductions summary % was not found.', p_summary_id using errcode = 'P0001';
  end if;

  if v_summary.status <> 'finalized' then
    raise exception 'Deductions summary % is not finalized.', p_summary_id using errcode = 'P0001';
  end if;

  if p_import_job_id is not null then
    select *
    into v_existing_job
    from public.deduction_payroll_import_jobs
    where import_job_id = p_import_job_id
    for update;

    if found and v_existing_job.status = 'completed' then
      return jsonb_build_object(
        'import_job_id', p_import_job_id,
        'idempotent_replay', true,
        'imported_employees', coalesce(v_existing_job.imported_employees, 0),
        'imported_total', coalesce(v_existing_job.imported_total, 0),
        'matched_employees', v_existing_job.matched_employees,
        'unmatched_employees', v_existing_job.unmatched_employees,
        'target_batch_id', v_existing_job.batch_id,
        'target_batch_month', v_summary.month,
        'target_batch_year', v_summary.year
      );
    end if;
  end if;

  -- ADD-on-top is not idempotent: a finalized summary may be imported to payroll
  -- only once. Block a second import (any different job id) to prevent doubling.
  if exists (
    select 1
    from public.deduction_payroll_import_jobs
    where summary_id = p_summary_id
      and status = 'completed'
  ) then
    raise exception 'Deductions summary % was already imported to payroll; re-import is blocked to prevent double deductions.', p_summary_id using errcode = 'P0001';
  end if;

  select *
  into v_batch
  from public.salary_batches
  where month = v_summary.month
    and year = v_summary.year
  order by created_at desc, id desc
  limit 1
  for update;

  if not found then
    raise exception 'No payroll batch exists for deductions month %.', v_summary.month_key using errcode = 'P0001';
  end if;

  if v_batch.status not in ('part1_paid', 'adjustments_open', 'part2_ready', 'under_review', 'rejected') then
    raise exception 'Payroll batch cannot import deductions while status is %.', v_batch.status using errcode = 'P0001';
  end if;

  with line_totals as (
    select
      lower(employee_code) as normalized_hr_id,
      min(employee_code) as employee_code,
      min(employee_name) as employee_name,
      sum(applied_amount) filter (where payroll_column = 'crm')::numeric(14, 2) as crm_total,
      sum(applied_amount) filter (where payroll_column = 'finger_print')::numeric(14, 2) as finger_print_total,
      sum(applied_amount) filter (where payroll_column = 'unpaid_vacations')::numeric(14, 2) as unpaid_vacations_total,
      sum(applied_amount)::numeric(14, 2) as total_amount
    from public.deduction_monthly_summary_lines
    where summary_id = p_summary_id
    group by lower(employee_code)
  ),
  unmatched as (
    select
      lt.employee_code,
      lt.employee_name,
      lt.total_amount
    from line_totals lt
    where not exists (
      select 1
      from public.salary_records sr
      where sr.batch_id = v_batch.id
        and (
          lower(sr.hr_id) = lt.normalized_hr_id
          or lower(coalesce(sr.employee_code, '')) = lt.normalized_hr_id
        )
    )
  )
  select coalesce(jsonb_agg(to_jsonb(unmatched) order by employee_code), '[]'::jsonb)
  into v_unmatched_employees
  from unmatched;

  if jsonb_array_length(v_unmatched_employees) > 0 then
    raise exception 'Deductions import has unmatched payroll employees for month %.', v_summary.month_key using errcode = 'P0001';
  end if;

  if p_import_job_id is not null then
    insert into public.deduction_payroll_import_jobs (
      import_job_id,
      summary_id,
      batch_id,
      month_key,
      actor_login_id,
      status,
      unmatched_employees,
      created_at
    ) values (
      p_import_job_id,
      p_summary_id,
      v_batch.id,
      v_summary.month_key,
      coalesce(nullif(p_actor_login_id, ''), 'system'),
      'pending',
      v_unmatched_employees,
      now()
    )
    on conflict (import_job_id) do update
      set status = 'pending',
          summary_id = excluded.summary_id,
          batch_id = excluded.batch_id,
          month_key = excluded.month_key,
          actor_login_id = excluded.actor_login_id,
          unmatched_employees = excluded.unmatched_employees,
          created_at = now(),
          error_message = null;
  end if;

  begin
    with line_totals as (
      select
        lower(employee_code) as normalized_hr_id,
        min(employee_code) as employee_code,
        sum(applied_amount) filter (where payroll_column = 'crm')::numeric(14, 2) as crm_total,
        sum(applied_amount) filter (where payroll_column = 'finger_print')::numeric(14, 2) as finger_print_total,
        sum(applied_amount) filter (where payroll_column = 'unpaid_vacations')::numeric(14, 2) as unpaid_vacations_total,
        sum(applied_amount)::numeric(14, 2) as total_amount
      from public.deduction_monthly_summary_lines
      where summary_id = p_summary_id
      group by lower(employee_code)
    ),
    target_rows as (
      select
        sr.id,
        sr.hr_id,
        coalesce(sr.crm, 0)::numeric as old_crm,
        coalesce(sr.finger_print, 0)::numeric as old_finger_print,
        coalesce(sr.unpaid_vacations, 0)::numeric as old_unpaid_vacations,
        coalesce(lt.crm_total, 0)::numeric as add_crm,
        coalesce(lt.finger_print_total, 0)::numeric as add_finger_print,
        coalesce(lt.unpaid_vacations_total, 0)::numeric as add_unpaid_vacations,
        coalesce(lt.total_amount, 0)::numeric as add_total_amount
      from public.salary_records sr
      left join line_totals lt
        on (
          lower(sr.hr_id) = lt.normalized_hr_id
          or lower(coalesce(sr.employee_code, '')) = lt.normalized_hr_id
        )
      where sr.batch_id = v_batch.id
    ),
    updated_rows as (
      update public.salary_records sr
      set
        crm = tr.old_crm + tr.add_crm,
        finger_print = tr.old_finger_print + tr.add_finger_print,
        unpaid_vacations = tr.old_unpaid_vacations + tr.add_unpaid_vacations,
        total_deductions = coalesce(sr.total_deductions, 0)
          + (tr.add_crm + tr.add_finger_print + tr.add_unpaid_vacations),
        second_part = greatest(
          0,
          coalesce(sr.second_part, 0)
            - (tr.add_crm + tr.add_finger_print + tr.add_unpaid_vacations)
        ),
        month_salary = greatest(
          0,
          coalesce(sr.month_salary, coalesce(sr.first_part, 0) + coalesce(sr.second_part, 0))
            - (tr.add_crm + tr.add_finger_print + tr.add_unpaid_vacations)
        )
      from target_rows tr
      where sr.id = tr.id
        and (tr.add_crm + tr.add_finger_print + tr.add_unpaid_vacations) > 0
      returning sr.id
    ),
    matched as (
      select
        sr.hr_id,
        tr.add_total_amount as imported_total
      from target_rows tr
      join public.salary_records sr on sr.id = tr.id
      where tr.add_total_amount > 0
    )
    select
      count(*)::integer,
      coalesce(sum(imported_total), 0)::numeric(14, 2),
      coalesce(jsonb_agg(to_jsonb(matched) order by hr_id), '[]'::jsonb)
    into
      v_imported_employees,
      v_imported_total,
      v_matched_employees
    from matched;

    update public.deduction_decisions dd
    set payroll_handoff_status = 'Imported to Payroll'
    where dd.id in (
      select decision_id
      from public.deduction_monthly_summary_lines
      where summary_id = p_summary_id
    );

    if p_import_job_id is not null then
      update public.deduction_payroll_import_jobs
      set
        status = 'completed',
        imported_employees = v_imported_employees,
        imported_total = v_imported_total,
        matched_employees = v_matched_employees,
        unmatched_employees = v_unmatched_employees,
        completed_at = now(),
        error_message = null
      where import_job_id = p_import_job_id;
    end if;
  exception when others then
    if p_import_job_id is not null then
      update public.deduction_payroll_import_jobs
      set
        status = 'failed',
        error_message = sqlerrm,
        completed_at = now()
      where import_job_id = p_import_job_id;
    end if;
    raise;
  end;

  return jsonb_build_object(
    'import_job_id', p_import_job_id,
    'idempotent_replay', false,
    'imported_employees', v_imported_employees,
    'imported_total', v_imported_total,
    'matched_employees', v_matched_employees,
    'unmatched_employees', v_unmatched_employees,
    'target_batch_id', v_batch.id,
    'target_batch_month', v_batch.month,
    'target_batch_year', v_batch.year
  );
end;
$$;


--
-- TOC entry 858 (class 1255 OID 16643)
-- Name: phx_insert_attendance_raw_punch(text, text, text, timestamp with time zone, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_insert_attendance_raw_punch(p_device_id text, p_device_user_id text, p_employee_hr_id text, p_punch_time timestamp with time zone, p_punch_type text, p_verify_mode text, p_raw_payload jsonb, p_source_run_id text) RETURNS bigint
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into public.attendance_raw_punches (
    device_id,
    device_user_id,
    employee_hr_id,
    punch_time,
    punch_type,
    verify_mode,
    raw_payload,
    source_run_id,
    ingested_at
  )
  values (
    p_device_id,
    p_device_user_id,
    p_employee_hr_id,
    p_punch_time,
    p_punch_type,
    p_verify_mode,
    coalesce(p_raw_payload, '{}'::jsonb),
    p_source_run_id,
    now()
  )
  on conflict do nothing
  returning id;
$$;


--
-- TOC entry 9680 (class 0 OID 0)
-- Dependencies: 858
-- Name: FUNCTION phx_insert_attendance_raw_punch(p_device_id text, p_device_user_id text, p_employee_hr_id text, p_punch_time timestamp with time zone, p_punch_type text, p_verify_mode text, p_raw_payload jsonb, p_source_run_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.phx_insert_attendance_raw_punch(p_device_id text, p_device_user_id text, p_employee_hr_id text, p_punch_time timestamp with time zone, p_punch_type text, p_verify_mode text, p_raw_payload jsonb, p_source_run_id text) IS 'Idempotent single raw-punch insert for the fingerprint attendance agent. Uses ON CONFLICT DO NOTHING so re-pushed punches are silently ignored at the database level (no duplicate-key ERROR logged). Returns the new id, or NULL when the punch already existed.';


--
-- TOC entry 859 (class 1255 OID 16644)
-- Name: phx_marketing_coverage_export_sales_detail(uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_marketing_coverage_export_sales_detail(p_request_ids uuid[], p_exclude_product_codes text[] DEFAULT '{LA003,LA004,SS001}'::text[]) RETURNS TABLE(request_id uuid, distributor_code text, distributor_name text, invoice_period text, product_code text, product_name text, customer_code text, customer_name text, region_name text, qty numeric, value numeric)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with excl as (
    select array(select upper(btrim(c)) from unnest(coalesce(p_exclude_product_codes, '{}'::text[])) c) as codes
  ),
  req as (
    select mr.id, mr.pay_date, greatest(coalesce(mr.roi_duration_months, 1), 1) as months
    from public.marketing_requests mr
    where mr.id = any(p_request_ids) and mr.pay_date is not null
  ),
  win as (
    select req.id as request_id, to_char(g, 'YYYY-MM') as period
    from req
    cross join lateral generate_series(
      date_trunc('month', req.pay_date),
      date_trunc('month', req.pay_date) + make_interval(months => req.months - 1),
      interval '1 month'
    ) g
  ),
  req_products as (
    select distinct mrp.request_id, sp.product_code
    from public.marketing_request_products mrp
    join public.marketing_products mp on mp.id = mrp.product_id
    join public.source_of_sales_products sp
      on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
    cross join excl
    where mrp.request_id = any(p_request_ids)
      and upper(btrim(sp.product_code)) <> all(excl.codes)
  ),
  req_targets as (
    -- join source_of_sales_distributors so a rollup code with no SoS distributor row is
    -- dropped IDENTICALLY to phx_marketing_request_roi_actuals / the single-request RPC.
    select distinct
      mrph.request_id,
      sd.distributor_code as family_code,
      ru.parent_distributor_code,
      mpdc.normalized_pharmacy_code as customer_code
    from public.marketing_request_pharmacies mrph
    join public.marketing_pharmacy_distributor_codes mpdc on mpdc.id = mrph.distributor_code_id
    join public.marketing_distributors md on md.id = mpdc.distributor_id
    join public.marketing_roi_distributor_rollup ru on ru.marketing_normalized_name = md.normalized_name
    join public.source_of_sales_distributors sd on sd.distributor_code = ru.sos_distributor_code
    where mrph.request_id = any(p_request_ids)
      and coalesce(btrim(mpdc.normalized_pharmacy_code), '') <> ''
  ),
  target_products as (
    select distinct rt.request_id, rt.family_code, rt.parent_distributor_code, rt.customer_code, rp.product_code
    from req_targets rt
    join req_products rp on rp.request_id = rt.request_id
  ),
  hits as (
    -- dedup per (request, matched SoS row): the SAME underlying sale can legitimately
    -- satisfy more than one request in the batch, but must never appear twice for the
    -- SAME request (mirrors the single-request RPC's `distinct on (r.id)` exactly, just
    -- scoped per request instead of globally, since this now covers many requests at once).
    select distinct on (tp.request_id, r.id)
      tp.request_id,
      r.id as row_id,
      tp.parent_distributor_code,
      r.invoice_period,
      r.product_code,
      coalesce(sp.product_name, r.product_name, r.product_code) as product_name,
      tp.customer_code,
      r.client_name as customer_name,
      r.region_name,
      r.qty as qty,
      case when coalesce(r.is_direct, false)
           then coalesce(r.value, 0)
           else r.qty * (1 - coalesce(r.discount, 0)) * coalesce(sp.factory_price, 0)
      end as value
    from target_products tp
    join win on win.request_id = tp.request_id
    join public.source_of_sales_import_rows r
      on r.distributor_code = tp.family_code
     and lower(btrim(regexp_replace(coalesce(r.client_code, ''), '\s+', ' ', 'g'))) = tp.customer_code
     and upper(btrim(r.product_code)) = upper(btrim(tp.product_code))
     and r.invoice_period = win.period
     and r.validation_state = 'valid'
    join public.source_of_sales_import_batches b on b.id = r.batch_id and b.status = 'validated'
    join public.source_of_sales_products sp on upper(btrim(sp.product_code)) = upper(btrim(r.product_code))
    order by tp.request_id, r.id
  )
  select
    hits.request_id,
    hits.parent_distributor_code as distributor_code,
    coalesce(sd.distributor_name, hits.parent_distributor_code) as distributor_name,
    hits.invoice_period,
    hits.product_code,
    hits.product_name,
    hits.customer_code,
    hits.customer_name,
    hits.region_name,
    hits.qty::numeric,
    hits.value::numeric
  from hits
  left join public.source_of_sales_distributors sd on sd.distributor_code = hits.parent_distributor_code
  order by hits.request_id, hits.invoice_period, hits.parent_distributor_code, hits.product_code;
$$;


