--
-- TOC entry 868 (class 1255 OID 16668)
-- Name: phx_monthly_closing_direct(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_monthly_closing_direct(p_line text, p_period text) RETURNS TABLE(region_code text, product_code text, sales_units numeric, sales_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    f.region_code, f.product_code,
    sum(f.total_qty)   as sales_units,
    sum(f.direct_value) as sales_value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b
    on b.id = f.batch_id and b.status = 'validated'
  where f.period = p_period
    and lower(btrim(f.official_line)) = lower(btrim(p_line))
    and f.is_direct
    and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  group by f.region_code, f.product_code;
$$;


--
-- TOC entry 869 (class 1255 OID 16669)
-- Name: phx_monthly_closing_matrix(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_monthly_closing_matrix(p_line text, p_period text) RETURNS TABLE(area_code text, product_code text, sales_units numeric, sales_value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select
    f.area_code, f.product_code,
    sum(f.total_qty)                                       as sales_units,
    sum(f.effective_units * coalesce(p.factory_price, 0)) as sales_value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b
    on b.id = f.batch_id and b.status = 'validated'
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  where f.period = p_period
    and lower(btrim(f.official_line)) = lower(btrim(p_line))
    and not f.is_direct
    and upper(btrim(coalesce(f.product_code, ''))) not in ('LA003', 'LA004', 'SS001')
  group by f.area_code, f.product_code;
$$;


--
-- TOC entry 870 (class 1255 OID 16670)
-- Name: phx_normalize_terminal_employee_lifecycle_flags(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_normalize_terminal_employee_lifecycle_flags(p_employee_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_employee public.employees%rowtype;
begin
  if nullif(trim(coalesce(p_employee_hr_id, '')), '') is null then
    raise exception 'Employee HR ID is required.' using errcode = '22023';
  end if;

  update public.employees
  set
    payroll_eligible = false,
    organogram_visible = false,
    updated_at = now()
  where upper(hr_id) = upper(trim(p_employee_hr_id))
    and lower(coalesce(employment_status, 'active')) in ('resigned', 'terminated', 'inactive')
  returning *
  into v_employee;

  if not found then
    select *
    into v_employee
    from public.employees
    where upper(hr_id) = upper(trim(p_employee_hr_id));

    if not found then
      return jsonb_build_object('updated', false, 'reason', 'employee_not_found');
    end if;

    return jsonb_build_object(
      'updated', false,
      'reason', 'employee_not_terminal',
      'employee_status', v_employee.employment_status
    );
  end if;

  return jsonb_build_object(
    'updated', true,
    'employee_hr_id', v_employee.hr_id,
    'employee_status', v_employee.employment_status,
    'organogram_visible', v_employee.organogram_visible,
    'payroll_eligible', v_employee.payroll_eligible
  );
end;
$$;


