--
-- TOC entry 873 (class 1255 OID 16673)
-- Name: phx_prevent_closed_salary_batch_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_prevent_closed_salary_batch_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(current_setting('request.phx_allow_salary_batch_delete', true), '') = 'on' then
    return old;
  end if;

  if old.status in ('approved', 'locked') or old.part1_paid_at is not null then
    raise exception 'Payroll batch cannot be deleted after Part 1 is paid or while status is %.', old.status using errcode = 'P0001';
  end if;

  return old;
end;
$$;


--
-- TOC entry 874 (class 1255 OID 16674)
-- Name: phx_prevent_closed_salary_batch_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_prevent_closed_salary_batch_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if old.status in ('approved', 'locked') then
    if old.status = 'approved'
      and new.status = 'locked'
      and new.id is not distinct from old.id
      and new.month is not distinct from old.month
      and new.year is not distinct from old.year
      and new.file_name is not distinct from old.file_name
      and new.uploaded_by is not distinct from old.uploaded_by
      and new.approved_at is not distinct from old.approved_at
      and new.approved_by is not distinct from old.approved_by
      and new.part1_paid_at is not distinct from old.part1_paid_at
      and new.part1_paid_by is not distinct from old.part1_paid_by
      and new.part2_ready_at is not distinct from old.part2_ready_at
      and new.part2_ready_by is not distinct from old.part2_ready_by
      and new.rejected_reason is not distinct from old.rejected_reason
      and new.created_at is not distinct from old.created_at then
      return new;
    end if;

    raise exception 'Payroll batch cannot be updated while status is %.', old.status using errcode = 'P0001';
  end if;

  return new;
end;
$$;


--
-- TOC entry 875 (class 1255 OID 16675)
-- Name: phx_prevent_closed_salary_detail_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_prevent_closed_salary_detail_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch_id uuid;
  v_batch_status text;
  v_part1_paid_at timestamptz;
begin
  if tg_op = 'DELETE' then
    v_batch_id := old.batch_id;
  else
    v_batch_id := new.batch_id;
  end if;

  select status, part1_paid_at
  into v_batch_status, v_part1_paid_at
  from public.salary_batches
  where id = v_batch_id;

  if v_batch_status in ('approved', 'locked') then
    raise exception 'Payroll batch cannot be changed while status is %.', v_batch_status using errcode = 'P0001';
  end if;

  if tg_table_name = 'salary_records' and v_part1_paid_at is not null then
    if tg_op <> 'UPDATE' then
      raise exception 'Salary records cannot be inserted or deleted after Part 1 is paid.' using errcode = 'P0001';
    end if;

    if new.batch_id is distinct from old.batch_id
      or new.hr_id is distinct from old.hr_id
      or new.full_name is distinct from old.full_name
      or new.name_ar is distinct from old.name_ar
      or new.job_title is distinct from old.job_title
      or new.line is distinct from old.line
      or new.area is distinct from old.area
      or new.hire_date is distinct from old.hire_date
      or new.base_salary is distinct from old.base_salary
      or new.gross_salary is distinct from old.gross_salary
      or new.net_salary is distinct from old.net_salary
      or new.first_part is distinct from old.first_part
      or new.extra_cost_of_living is distinct from old.extra_cost_of_living
      or new.fuel_allowance is distinct from old.fuel_allowance
      or new.social_insurance is distinct from old.social_insurance
      or new.employment_income_tax is distinct from old.employment_income_tax
      or new.governmental_deductions is distinct from old.governmental_deductions
      or new.payment_mode is distinct from old.payment_mode then
      raise exception 'Part 1 salary fields cannot be changed after Part 1 is paid.' using errcode = 'P0001';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


--
-- TOC entry 876 (class 1255 OID 16676)
-- Name: phx_prevent_duplicate_salary_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_prevent_duplicate_salary_period() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if exists (
    select 1
    from public.salary_batches existing
    where existing.month = new.month
      and existing.year = new.year
      and existing.id is distinct from new.id
  ) then
    raise exception 'Payroll period %/% already has a batch.', new.month, new.year using errcode = '23505';
  end if;

  return new;
end;
$$;


--
-- TOC entry 877 (class 1255 OID 16677)
-- Name: phx_prevent_employee_hr_id_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_prevent_employee_hr_id_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.hr_id is distinct from old.hr_id then
    raise exception 'HR_ID is immutable after employee creation. Use the governed HR_ID rename workflow.';
  end if;

  return new;
end;
$$;


--
-- TOC entry 878 (class 1255 OID 16678)
-- Name: phx_prevent_terminal_employee_reactivation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_prevent_terminal_employee_reactivation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  old_status text := lower(trim(coalesce(old.employment_status, '')));
  new_status text := lower(trim(coalesce(new.employment_status, old.employment_status, '')));
  allow_override text := coalesce(current_setting('request.phx_allow_terminal_employee_reactivation', true), '');
begin
  if allow_override = 'on' then
    return new;
  end if;

  if old_status in ('resigned', 'terminated') and new_status not in ('resigned', 'terminated') then
    raise exception 'Terminal employees cannot be reactivated outside a governed workflow.'
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;


--
-- TOC entry 879 (class 1255 OID 16679)
-- Name: phx_reassign_replacement_ownership(text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_reassign_replacement_ownership(p_previous_hr_id text, p_replacement_hr_id text, p_effective_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_previous_hr_id text := upper(trim(coalesce(p_previous_hr_id, '')));
  v_replacement_hr_id text := upper(trim(coalesce(p_replacement_hr_id, '')));
  v_effective_date date := coalesce(p_effective_date, current_date);
  v_previous_status text;
  v_replacement_name text;
  v_replacement_status text;
  v_count integer := 0;
  v_result jsonb := '{}'::jsonb;
begin
  if v_previous_hr_id = '' or v_replacement_hr_id = '' then
    return jsonb_build_object('applied', false, 'reason', 'missing_hr_id');
  end if;

  if v_previous_hr_id = v_replacement_hr_id then
    return jsonb_build_object('applied', false, 'reason', 'same_hr_id');
  end if;

  select lower(coalesce(employment_status, 'active'))
  into v_previous_status
  from public.employees
  where hr_id = v_previous_hr_id;

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'previous_employee_not_found');
  end if;

  if v_previous_status not in ('resigned', 'terminated', 'inactive') then
    return jsonb_build_object('applied', false, 'reason', 'previous_employee_not_terminal');
  end if;

  select full_name, lower(coalesce(employment_status, 'active'))
  into v_replacement_name, v_replacement_status
  from public.employees
  where hr_id = v_replacement_hr_id
    and coalesce(payroll_eligible, true) is true
    and coalesce(organogram_visible, true) is true;

  if not found or v_replacement_status not in ('active', 'on_leave') then
    return jsonb_build_object('applied', false, 'reason', 'replacement_employee_not_active');
  end if;

  if to_regclass('public.app_auth_users') is not null then
    begin
      execute
        'update public.app_auth_users u
         set manager_hr_id = $2, updated_at = now()
         where u.is_active is true
           and (
             u.manager_hr_id = $1
             or exists (
               select 1
               from public.employees e
               where e.hr_id = u.hr_id
                 and e.pending_manager_replacement_for_hr_id = $1
             )
           )'
        using v_previous_hr_id, v_replacement_hr_id;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('app_auth_users_reassigned', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('app_auth_users_reassigned', null);
    end;
  end if;

  if to_regclass('public.user_access_profiles') is not null then
    begin
      execute
        'update public.user_access_profiles u
         set manager_hr_id = $2, updated_at = now()
         where u.is_active is true
           and (
             u.manager_hr_id = $1
             or exists (
               select 1
               from public.employees e
               where e.hr_id = u.hr_id
                 and e.pending_manager_replacement_for_hr_id = $1
             )
           )'
        using v_previous_hr_id, v_replacement_hr_id;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('user_access_profiles_reassigned', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('user_access_profiles_reassigned', null);
    end;
  end if;

  update public.employees
  set
    manager_hr_id = v_replacement_hr_id,
    pending_manager_replacement_for_hr_id = null,
    updated_at = now()
  where (
      manager_hr_id = v_previous_hr_id
      or pending_manager_replacement_for_hr_id = v_previous_hr_id
    )
    and lower(coalesce(employment_status, 'active')) in ('active', 'on_leave');

  get diagnostics v_count = row_count;
  v_result := v_result || jsonb_build_object('employees_reassigned', v_count);

  update public.position_vacancies
  set
    manager_hr_id = v_replacement_hr_id,
    manager_name = v_replacement_name,
    manager_replacement_for_hr_id = null,
    note = case
      when coalesce(note, '') ilike '%Replacement ownership engine:%' then note
      else concat_ws(
        E'\n',
        nullif(note, ''),
        'Replacement ownership engine: moved live vacancy manager from '
          || v_previous_hr_id || ' to ' || v_replacement_hr_id || ' on ' || current_date::text || '.'
      )
    end,
    updated_at = now()
  where (
      manager_hr_id = v_previous_hr_id
      or manager_replacement_for_hr_id = v_previous_hr_id
    )
    and lower(coalesce(status, 'open')) = 'open';

  get diagnostics v_count = row_count;
  v_result := v_result || jsonb_build_object('vacancies_reassigned', v_count);

  if to_regclass('public.sales_records') is not null then
    begin
      execute
        'update public.sales_records
         set manager_hr_id = $2
         where manager_hr_id = $1
           and (
             year > extract(year from $3::date)::integer
             or (
               year = extract(year from $3::date)::integer
               and month >= extract(month from $3::date)::integer
             )
           )'
        using v_previous_hr_id, v_replacement_hr_id, v_effective_date;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('sales_records_reassigned', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('sales_records_reassigned', null);
    end;
  end if;

  v_result := v_result || jsonb_build_object('sales_targets_reassigned', null);

  return jsonb_build_object(
    'applied', true,
    'previous_hr_id', v_previous_hr_id,
    'replacement_hr_id', v_replacement_hr_id,
    'effective_date', v_effective_date
  ) || v_result;
end;
$_$;


--
-- TOC entry 880 (class 1255 OID 16680)
-- Name: phx_reconcile_stale_replacement_vacancies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_reconcile_stale_replacement_vacancies() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_checked integer := 0;
  v_closed integer := 0;
  r record;
  v_replacement record;
begin
  for r in
    select
      v.id as vacancy_id,
      d.hr_id as departed_hr_id,
      d.manager_hr_id as departed_manager_hr_id,
      d.line_id as departed_line_id,
      d.job_title as departed_job_title,
      coalesce(d.last_working_date, d.resignation_date) as departed_effective_date
    from public.position_vacancies v
    join public.employees d on d.hr_id = v.replacement_for_hr_id
    where lower(coalesce(v.status, 'open')) = 'open'
      and nullif(trim(coalesce(v.replacement_for_hr_id, '')), '') is not null
      and d.manager_hr_id is not null
      and d.line_id is not null
      and nullif(trim(coalesce(d.job_title, '')), '') is not null
  loop
    v_checked := v_checked + 1;

    select a.hr_id
    into v_replacement
    from public.employees a
    where a.manager_hr_id = r.departed_manager_hr_id
      and a.line_id = r.departed_line_id
      and lower(trim(a.job_title)) = lower(trim(r.departed_job_title))
      and lower(coalesce(a.employment_status, 'active')) in ('active', 'on_leave')
      and a.hr_id <> r.departed_hr_id
      and (
        r.departed_effective_date is null
        or a.hire_date is null
        or a.hire_date >= r.departed_effective_date
      )
    order by a.hire_date asc nulls last
    limit 1;

    if found then
      update public.position_vacancies
      set
        status = 'filled',
        filled_by_hr_id = v_replacement.hr_id,
        filled_at = now(),
        replacement_for_hr_id = null,
        note = concat_ws(
          E'\n',
          nullif(note, ''),
          'Auto-closed by stale-replacement-vacancy reconciliation: seat for '
            || r.departed_hr_id || ' was already filled by ' || v_replacement.hr_id
            || ' on ' || current_date::text || '.'
        ),
        updated_at = now()
      where id = r.vacancy_id;

      v_closed := v_closed + 1;
    end if;
  end loop;

  return jsonb_build_object('checked', v_checked, 'closed', v_closed);
exception
  when undefined_column then
    raise notice 'Stale-replacement-vacancy reconciliation skipped because expected lifecycle/vacancy columns are missing.';
    return jsonb_build_object('applied', false, 'reason', 'missing_schema_column');
end;
$$;


--
-- TOC entry 881 (class 1255 OID 16681)
-- Name: phx_refresh_marketing_roi_facts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_refresh_marketing_roi_facts(p_batch_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
declare
  v_run_id           uuid;
  v_lock_key         bigint := abs(hashtext('marketing_roi_refresh')::bigint);
  v_affected_periods text[] := '{}';
  v_affected_ids     uuid[]  := '{}';
  v_source_batch_ids uuid[]  := '{}';
  v_min_period       text;
  v_max_period       text;
  v_cnt_requests     bigint := 0;
  v_cnt_trends       bigint := 0;
  v_cnt_lines        bigint := 0;
  v_cnt_products     bigint := 0;
  v_cnt_regions      bigint := 0;
  v_cnt_distributors bigint := 0;
  v_cnt_customers    bigint := 0;
  v_cnt_request_geo  bigint := 0;
begin
  if not pg_try_advisory_xact_lock(v_lock_key) then
    insert into marketing_roi_refresh_runs
      (triggered_by, trigger_batch_id, status, calculation_version)
    values
      (case when p_batch_id is not null then 'sos_import' else 'admin_manual' end,
       p_batch_id, 'skipped', '3')
    returning id into v_run_id;
    return jsonb_build_object('status', 'skipped', 'runId', v_run_id);
  end if;

  insert into marketing_roi_refresh_runs
    (triggered_by, trigger_batch_id, status, calculation_version)
  values
    (case when p_batch_id is not null then 'sos_import' else 'admin_manual' end,
     p_batch_id, 'running', '3')
  returning id into v_run_id;

  begin
    if p_batch_id is not null then
      select
        coalesce(array_agg(distinct invoice_period order by invoice_period), '{}'),
        min(invoice_period),
        max(invoice_period)
      into v_affected_periods, v_min_period, v_max_period
      from source_of_sales_import_rows
      where batch_id = p_batch_id and validation_state = 'valid';

      v_source_batch_ids := array[p_batch_id];

      if v_min_period is not null then
        select coalesce(array_agg(mr.id), '{}')
        into v_affected_ids
        from marketing_requests mr
        where mr.pay_date is not null
          and to_char(date_trunc('month', mr.pay_date), 'YYYY-MM') <= v_max_period
          and to_char(
                date_trunc('month', mr.pay_date)
                + make_interval(months => greatest(coalesce(mr.roi_duration_months,1),1) - 1),
                'YYYY-MM'
              ) >= v_min_period;
      end if;

    else
      select coalesce(array_agg(distinct invoice_period order by invoice_period), '{}')
      into v_affected_periods
      from source_of_sales_import_rows
      where validation_state = 'valid';

      select coalesce(array_agg(distinct id), '{}')
      into v_source_batch_ids
      from source_of_sales_import_batches
      where status = 'validated';

      select coalesce(array_agg(mr.id), '{}')
      into v_affected_ids
      from marketing_requests mr
      where mr.pay_date is not null;
    end if;

    if coalesce(array_length(v_affected_ids, 1), 0) = 0 then
      update marketing_roi_refresh_runs
      set status = 'success', finished_at = now(),
          affected_periods = v_affected_periods,
          row_counts = '{"requests":0,"trends":0,"lines":0,"products":0,"regions":0,"distributors":0,"customers":0,"requestGeo":0}'::jsonb
      where id = v_run_id;
      return jsonb_build_object('status','success','runId',v_run_id,'affectedRequests',0);
    end if;

    delete from marketing_roi_request_facts
    where request_id = any(v_affected_ids);

    delete from marketing_roi_request_geo_facts
    where request_id = any(v_affected_ids);

    delete from marketing_roi_trend_facts
    where period in (
      select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM')
      from marketing_requests where id = any(v_affected_ids)
    );
    delete from marketing_roi_line_facts
    where period in (
      select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM')
      from marketing_requests where id = any(v_affected_ids)
    );
    delete from marketing_roi_product_facts
    where period in (
      select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM')
      from marketing_requests where id = any(v_affected_ids)
    );
    delete from marketing_roi_region_facts
    where period in (
      select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM')
      from marketing_requests where id = any(v_affected_ids)
    );
    delete from marketing_roi_distributor_facts
    where period in (
      select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM')
      from marketing_requests where id = any(v_affected_ids)
    );
    delete from marketing_roi_customer_facts
    where period in (
      select distinct to_char(date_trunc('month', pay_date), 'YYYY-MM')
      from marketing_requests where id = any(v_affected_ids)
    );

    with
    req_raw as materialized (
      select
        mr.id,
        mr.request_code,
        mr.pay_date,
        to_char(date_trunc('month', mr.pay_date), 'YYYY-MM') as pay_month,
        greatest(coalesce(mr.roi_duration_months,1),1)          as roi_duration_months,
        coalesce(mr.estimated_cost, 0)::numeric                 as estimated_cost,
        coalesce(mr.required_roi_value,
                 coalesce(mr.estimated_cost,0)*10)::numeric     as required_roi_value,
        coalesce(mr.expected_roi_value, 0)::numeric             as expected_roi_value,
        mr.customer_id,
        coalesce(l.name, 'Unassigned')                          as request_line,
        coalesce(mc.display_name, mr.customer_id::text)         as customer_name,
        mc.customer_code,
        mr.status                                               as request_status
      from marketing_requests mr
      left join employees emp_req
        on upper(btrim(emp_req.hr_id)) = upper(btrim(mr.requester_hr_id))
      left join lines l
        on l.id = coalesce(mr.line_id, emp_req.line_id)
      left join marketing_customers mc on mc.id = mr.customer_id
      where mr.id = any(v_affected_ids)
    ),
    req_products_all as materialized (
      select distinct
        mrp.request_id,
        upper(btrim(sp.product_code))                           as product_code,
        coalesce(sp.product_name, mp.product_name,
                 mrp.product_name_snapshot)                     as product_name,
        coalesce(nullif(btrim(sp.line),''),
                 nullif(btrim(mp.line),''),
                 nullif(btrim(mrp.line_snapshot),''),
                 'Unassigned')                                  as line_label,
        coalesce(mrp.expected_value, 0)::numeric                as expected_value,
        coalesce(mrp.value_share, 0)::numeric                   as value_share
      from marketing_request_products mrp
      join marketing_products mp on mp.id = mrp.product_id
      left join source_of_sales_products sp
        on lower(btrim(sp.normalized_product_name)) = lower(btrim(mp.normalized_name))
      where mrp.request_id in (select id from req_raw)
    ),
    req_targets_all as materialized (
      select distinct
        mrph.request_id,
        sd.distributor_code,
        coalesce(sd.distributor_name, md.display_name, sd.distributor_code) as distributor_name,
        sd.distributor_code                                     as family_code,
        mpdc.normalized_pharmacy_code                          as customer_code,
        mph.id                                                  as pharmacy_id,
        coalesce(mph.display_name,
                 mpdc.normalized_pharmacy_code)                 as pharmacy_name,
        cm.brick_id,
        cm.region_code,
        cm.area_code
      from marketing_request_pharmacies mrph
      join marketing_pharmacy_distributor_codes mpdc
        on mpdc.id = mrph.distributor_code_id
      join marketing_distributors md on md.id = mpdc.distributor_id
      join marketing_pharmacies mph on mph.id = mrph.pharmacy_id
      join (
        select distinct marketing_normalized_name, parent_distributor_code
        from marketing_roi_distributor_rollup
      ) ru on ru.marketing_normalized_name = md.normalized_name
      join source_of_sales_distributors sd
        on sd.distributor_code = ru.parent_distributor_code
      left join lateral (
        select cmx.brick_id, cmx.region_code, cmx.area_code
        from source_of_sales_customer_map cmx
        where lower(btrim(regexp_replace(coalesce(cmx.customer_code,''),'\s+',' ','g')))
                = mpdc.normalized_pharmacy_code
          and cmx.active
          and (
            cmx.distributor_code = sd.distributor_code
            or exists (
              select 1 from marketing_roi_distributor_rollup rcm
              where rcm.parent_distributor_code = sd.distributor_code
                and rcm.sos_distributor_code = cmx.distributor_code
            )
          )
        order by (cmx.distributor_code = sd.distributor_code) desc,
                 cmx.region_code nulls last
        limit 1
      ) cm on true
      where mrph.request_id in (select id from req_raw)
        and coalesce(btrim(mpdc.normalized_pharmacy_code),'') <> ''
        and coalesce(mpdc.active, true)
    ),
    req as materialized (
      select
        rr.*,
        coalesce(
          nullif(btrim(rr.request_line),''),
          (select max(rpa.line_label) from req_products_all rpa
           where rpa.request_id = rr.id),
          'Unassigned'
        ) as line_label
      from req_raw rr
    ),
    req_products as materialized (
      select rpa.* from req_products_all rpa
      join req on req.id = rpa.request_id
    ),
    req_targets as materialized (
      select rta.* from req_targets_all rta
      join req on req.id = rta.request_id
    ),
    product_rollups as (
      select
        request_id,
        count(*)::numeric                             as product_count,
        coalesce(sum(nullif(value_share,0)),0)::numeric as value_share_total,
        coalesce(sum(expected_value),0)::numeric      as expected_total
      from req_products
      group by request_id
    ),
    request_product_allocations as materialized (
      select
        rp.request_id,
        rp.product_code,
        rp.product_name,
        rp.line_label,
        rp.expected_value,
        rp.value_share,
        case
          when pr.value_share_total > 0 then rp.value_share / pr.value_share_total
          when pr.expected_total > 0    then rp.expected_value / pr.expected_total
          when pr.product_count > 0     then 1 / pr.product_count
          else 0
        end as share
      from req_products rp
      join product_rollups pr on pr.request_id = rp.request_id
    ),
    target_rollups as (
      select request_id, count(*)::numeric as target_count
      from req_targets group by request_id
    ),
    request_target_allocations as materialized (
      select
        rt.*,
        case when tr.target_count > 0 then 1 / tr.target_count else 0 end as share
      from req_targets rt
      join target_rollups tr on tr.request_id = rt.request_id
    ),
    periods as materialized (
      select req.id,
             array_agg(to_char(g,'YYYY-MM')) as periods
      from req
      cross join lateral generate_series(
        date_trunc('month', req.pay_date),
        date_trunc('month', req.pay_date)
          + make_interval(months => req.roi_duration_months - 1),
        interval '1 month'
      ) as g
      group by req.id
    ),
    target_products as materialized (
      select distinct
        rt.request_id,
        rt.distributor_code,
        rt.customer_code,
        rt.brick_id,
        rpa.product_code
      from req_targets rt
      join request_product_allocations rpa on rpa.request_id = rt.request_id
      where rpa.product_code is not null
    ),
    exact_hits as materialized (
      select distinct
        tp.request_id,
        r.id                                                     as row_id,
        tp.distributor_code,
        coalesce(sd.distributor_name, tp.distributor_code)      as distributor_name,
        lower(btrim(regexp_replace(coalesce(r.client_code,''),'\s+',' ','g'))) as client_code,
        nullif(btrim(r.client_name),'')                         as client_name,
        r.region_code,
        coalesce(sr.region_name, r.region_name, r.region_code)  as region_name,
        nullif(btrim(r.brick_id),'')                            as brick_id,
        upper(btrim(r.product_code))                            as product_code,
        coalesce(sp.product_name, r.product_name, r.product_code) as product_name,
        coalesce(nullif(btrim(sp.line),''),
                 nullif(btrim(r.official_line),''),
                 'Unassigned')                                  as line_label,
        coalesce(r.qty,0)::numeric                              as units,
        (case
          when coalesce(r.is_direct, false) then coalesce(r.value, 0)
          else coalesce(r.qty,0) * (1 - coalesce(r.discount,0)) * coalesce(sp.factory_price,0)
        end)::numeric                                           as sales_value,
        'exact'::text                                           as match_type
      from target_products tp
      join periods on periods.id = tp.request_id
      join marketing_roi_distributor_rollup rr_exact
        on rr_exact.parent_distributor_code = tp.distributor_code
      join source_of_sales_import_rows r
        on r.distributor_code = rr_exact.sos_distributor_code
       and lower(btrim(regexp_replace(coalesce(r.client_code,''),'\s+',' ','g')))
             = tp.customer_code
       and upper(btrim(r.product_code)) = upper(btrim(tp.product_code))
       and r.invoice_period = any(periods.periods)
       and r.validation_state = 'valid'
      join source_of_sales_import_batches b
        on b.id = r.batch_id and b.status = 'validated'
      join source_of_sales_products sp
        on upper(btrim(sp.product_code)) = upper(btrim(r.product_code))
      left join source_of_sales_distributors sd
        on sd.distributor_code = tp.distributor_code
      left join source_of_sales_regions sr on sr.region_code = r.region_code
    ),
    all_hits as materialized (
      select * from exact_hits
    ),
    actuals as materialized (
      select
        request_id,
        coalesce(sum(sales_value),0)::numeric  as actual_value,
        coalesce(sum(units),0)::numeric         as actual_units,
        count(distinct row_id)::integer                                          as sales_rows,
        count(distinct row_id) filter (where match_type='exact')::integer        as exact_sales_rows,
        count(distinct row_id) filter (where match_type='fallback')::integer     as fallback_sales_rows
      from all_hits
      group by request_id
    ),
    request_rows_base as materialized (
      select
        req.id,
        req.request_code,
        req.pay_month,
        req.roi_duration_months,
        req.estimated_cost,
        req.required_roi_value,
        req.expected_roi_value,
        req.customer_id,
        req.customer_name,
        req.customer_code,
        req.line_label,
        req.request_status,
        coalesce(a.actual_value, 0)::numeric         as actual_sales_value,
        coalesce(a.actual_units, 0)::numeric          as actual_sales_units,
        coalesce(a.sales_rows, 0)::integer            as sales_rows,
        coalesce(a.exact_sales_rows, 0)::integer      as exact_sales_rows,
        coalesce(a.fallback_sales_rows, 0)::integer   as fallback_sales_rows,
        case
          when coalesce(a.sales_rows,0) = 0 then 'no_sales'
          else 'exact_customer'
        end as attribution_quality,
        case
          when coalesce(a.sales_rows,0) = 0
            then 'no_data'
          when coalesce(a.actual_value,0) >= req.required_roi_value
            then 'on_track'
          else 'behind'
        end as actual_roi_status,
        case
          when req.required_roi_value > 0
            then coalesce(a.actual_value,0) / req.required_roi_value
          when coalesce(a.actual_value,0) > 0 then 1
          else 0
        end as actual_coverage_ratio,
        greatest(req.required_roi_value - coalesce(a.actual_value,0), 0)::numeric as coverage_gap,
        greatest(req.expected_roi_value - coalesce(a.actual_value,0), 0)::numeric as expected_gap
      from req
      left join actuals a on a.request_id = req.id
    ),
    request_rows as materialized (
      select
        rrb.*,
        case
          when rrb.actual_roi_status = 'on_track'         then 'monitor'
          when rrb.attribution_quality = 'no_sales'       then 'mapping_review'
          when rrb.actual_coverage_ratio < 0.5
               and rrb.coverage_gap > 0                   then 'high_risk_gap'
          else 'follow_up'
        end as recommended_action
      from request_rows_base rrb
    ),
    request_rows_approved as materialized (
      select *
      from request_rows
      where request_status in ('approved','active','roi_tracking','closed','finance_hold')
    ),
    actuals_by_line as (
      select
        rr.pay_month,
        ah.line_label,
        sum(ah.sales_value)::numeric as actual_sales_value
      from all_hits ah
      join request_rows_approved rr on rr.id = ah.request_id
      group by rr.pay_month, ah.line_label
    ),
    actuals_by_product as (
      select
        rr.pay_month,
        ah.product_code,
        sum(ah.sales_value)::numeric as actual_sales_value
      from all_hits ah
      join request_rows_approved rr on rr.id = ah.request_id
      group by rr.pay_month, ah.product_code
    ),
    actuals_by_region as (
      select
        rr.pay_month,
        ah.region_code,
        ah.line_label,
        sum(ah.sales_value)::numeric as actual_sales_value
      from all_hits ah
      join request_rows_approved rr on rr.id = ah.request_id
      where ah.region_code is not null
      group by rr.pay_month, ah.region_code, ah.line_label
    ),
    actuals_by_distributor as (
      select
        rr.pay_month,
        ah.distributor_code,
        ah.line_label,
        sum(ah.sales_value)::numeric as actual_sales_value
      from all_hits ah
      join request_rows_approved rr on rr.id = ah.request_id
      group by rr.pay_month, ah.distributor_code, ah.line_label
    ),
    actuals_by_customer_dist as (
      select
        rr.pay_month,
        rr.customer_id,
        ah.distributor_code,
        sum(ah.sales_value)::numeric as actual_sales_value,
        sum(ah.units)::numeric       as actual_sales_units
      from all_hits ah
      join request_rows_approved rr on rr.id = ah.request_id
      where rr.customer_id is not null
      group by rr.pay_month, rr.customer_id, ah.distributor_code
    ),
    actuals_by_request_geo as (
      select
        ah.request_id,
        ah.distributor_code,
        ah.region_code,
        sum(ah.sales_value)::numeric        as actual_sales_value,
        sum(ah.units)::numeric              as actual_sales_units,
        count(distinct ah.row_id)::integer  as sales_rows
      from all_hits ah
      group by ah.request_id, ah.distributor_code, ah.region_code
    ),
    ins_requests as (
      insert into marketing_roi_request_facts (
        refresh_run_id, request_id, request_code, pay_month, line_label,
        customer_id, customer_name, customer_code,
        estimated_cost, required_roi_value, expected_roi_value,
        actual_sales_value, actual_sales_units,
        sales_rows, exact_sales_rows, fallback_sales_rows,
        attribution_quality, actual_roi_status, actual_coverage_ratio,
        coverage_gap, expected_gap, recommended_action,
        source_batch_ids, source_periods, calculation_version,
        request_status
      )
      select
        v_run_id, rr.id, rr.request_code, rr.pay_month, rr.line_label,
        rr.customer_id, rr.customer_name, rr.customer_code,
        rr.estimated_cost, rr.required_roi_value, rr.expected_roi_value,
        rr.actual_sales_value, rr.actual_sales_units,
        rr.sales_rows, rr.exact_sales_rows, rr.fallback_sales_rows,
        rr.attribution_quality, rr.actual_roi_status, rr.actual_coverage_ratio,
        rr.coverage_gap, rr.expected_gap, rr.recommended_action,
        v_source_batch_ids, p.periods, '3', rr.request_status
      from request_rows rr
      left join periods p on p.id = rr.id
      returning 1
    ),
    ins_request_geo as (
      insert into marketing_roi_request_geo_facts (
        refresh_run_id, request_id, distributor_code, region_code,
        actual_sales_value, actual_sales_units, sales_rows, calculation_version
      )
      select
        v_run_id, abrg.request_id, abrg.distributor_code, abrg.region_code,
        abrg.actual_sales_value, abrg.actual_sales_units, abrg.sales_rows, '3'
      from actuals_by_request_geo abrg
      returning 1
    ),
    ins_trends as (
      insert into marketing_roi_trend_facts (
        refresh_run_id, period,
        request_count, marketing_cost, required_roi_value, expected_roi_value,
        actual_sales_value, coverage_gap,
        on_track_requests, behind_requests, no_data_requests,
        source_batch_ids, source_periods, calculation_version
      )
      select
        v_run_id, pay_month,
        count(*)::integer,
        sum(estimated_cost)::numeric,
        sum(required_roi_value)::numeric,
        sum(expected_roi_value)::numeric,
        sum(actual_sales_value)::numeric,
        sum(coverage_gap)::numeric,
        count(*) filter (where actual_roi_status='on_track')::integer,
        count(*) filter (where actual_roi_status='behind')::integer,
        count(*) filter (where actual_roi_status='no_data')::integer,
        v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved
      group by pay_month
      returning 1
    ),
    ins_lines as (
      insert into marketing_roi_line_facts (
        refresh_run_id, period, line_label,
        request_count, marketing_cost, required_roi_value, expected_roi_value,
        actual_sales_value, coverage_gap,
        on_track_requests, behind_requests, no_data_requests,
        source_batch_ids, source_periods, calculation_version
      )
      select
        v_run_id, rr.pay_month, rpa.line_label,
        count(distinct rr.id)::integer,
        sum(rr.estimated_cost * rpa.share)::numeric,
        sum(rr.required_roi_value * rpa.share)::numeric,
        sum(rr.expected_roi_value * rpa.share)::numeric,
        max(coalesce(abl.actual_sales_value, 0)),
        sum(rr.coverage_gap * rpa.share)::numeric,
        count(distinct rr.id) filter (where rr.actual_roi_status='on_track')::integer,
        count(distinct rr.id) filter (where rr.actual_roi_status='behind')::integer,
        count(distinct rr.id) filter (where rr.actual_roi_status='no_data')::integer,
        v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr
      join request_product_allocations rpa on rpa.request_id = rr.id
      left join actuals_by_line abl
        on abl.line_label = rpa.line_label and abl.pay_month = rr.pay_month
      group by rr.pay_month, rpa.line_label
      returning 1
    ),
    ins_products as (
      insert into marketing_roi_product_facts (
        refresh_run_id, period, product_code, product_name, line_label,
        request_count, marketing_cost, required_roi_value, expected_roi_value,
        actual_sales_value, actual_sales_units, coverage_gap,
        on_track_requests, behind_requests, no_data_requests,
        source_batch_ids, source_periods, calculation_version
      )
      select
        v_run_id, rr.pay_month, rpa.product_code,
        max(rpa.product_name), max(rpa.line_label),
        count(distinct rr.id)::integer,
        sum(rr.estimated_cost * rpa.share)::numeric,
        sum(rr.required_roi_value * rpa.share)::numeric,
        sum(rr.expected_roi_value * rpa.share)::numeric,
        max(coalesce(abp.actual_sales_value, 0)),
        coalesce(sum(rr.actual_sales_units * rpa.share), 0)::numeric,
        sum(rr.coverage_gap * rpa.share)::numeric,
        count(distinct rr.id) filter (where rr.actual_roi_status='on_track')::integer,
        count(distinct rr.id) filter (where rr.actual_roi_status='behind')::integer,
        count(distinct rr.id) filter (where rr.actual_roi_status='no_data')::integer,
        v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr
      join request_product_allocations rpa on rpa.request_id = rr.id
      left join actuals_by_product abp
        on abp.product_code = rpa.product_code and abp.pay_month = rr.pay_month
      where rpa.product_code is not null
      group by rr.pay_month, rpa.product_code
      returning 1
    ),
    ins_regions as (
      insert into marketing_roi_region_facts (
        refresh_run_id, period, region_code, region_name, line_label,
        request_count, marketing_cost, required_roi_value, expected_roi_value,
        actual_sales_value, coverage_gap,
        on_track_requests, behind_requests, no_data_requests,
        source_batch_ids, source_periods, calculation_version
      )
      select
        v_run_id, rr.pay_month,
        coalesce(rta.region_code, 'Unassigned'),
        max(coalesce(sr.region_name, rta.region_code, 'Unassigned')),
        rr.line_label,
        count(distinct rr.id)::integer,
        sum(rr.estimated_cost * rta.share)::numeric,
        sum(rr.required_roi_value * rta.share)::numeric,
        sum(rr.expected_roi_value * rta.share)::numeric,
        max(coalesce(abr.actual_sales_value, 0)),
        sum(rr.coverage_gap * rta.share)::numeric,
        count(distinct rr.id) filter (where rr.actual_roi_status='on_track')::integer,
        count(distinct rr.id) filter (where rr.actual_roi_status='behind')::integer,
        count(distinct rr.id) filter (where rr.actual_roi_status='no_data')::integer,
        v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr
      join request_target_allocations rta on rta.request_id = rr.id
      left join source_of_sales_regions sr on sr.region_code = rta.region_code
      left join actuals_by_region abr
        on abr.region_code = rta.region_code
       and abr.pay_month = rr.pay_month
       and abr.line_label = rr.line_label
      group by rr.pay_month, coalesce(rta.region_code, 'Unassigned'), rr.line_label
      returning 1
    ),
    ins_distributors as (
      insert into marketing_roi_distributor_facts (
        refresh_run_id, period, distributor_code, family_code, distributor_name,
        line_label,
        request_count, marketing_cost, required_roi_value, expected_roi_value,
        actual_sales_value, coverage_gap,
        on_track_requests, behind_requests, no_data_requests,
        source_batch_ids, source_periods, calculation_version
      )
      select
        v_run_id, rr.pay_month, rta.distributor_code, rta.family_code,
        max(rta.distributor_name), rr.line_label,
        count(distinct rr.id)::integer,
        sum(rr.estimated_cost * rta.share)::numeric,
        sum(rr.required_roi_value * rta.share)::numeric,
        sum(rr.expected_roi_value * rta.share)::numeric,
        max(coalesce(abd.actual_sales_value, 0)),
        sum(rr.coverage_gap * rta.share)::numeric,
        count(distinct rr.id) filter (where rr.actual_roi_status='on_track')::integer,
        count(distinct rr.id) filter (where rr.actual_roi_status='behind')::integer,
        count(distinct rr.id) filter (where rr.actual_roi_status='no_data')::integer,
        v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr
      join request_target_allocations rta on rta.request_id = rr.id
      left join actuals_by_distributor abd
        on abd.distributor_code = rta.distributor_code
       and abd.pay_month = rr.pay_month
       and abd.line_label = rr.line_label
      group by rr.pay_month, rta.distributor_code, rta.family_code, rr.line_label
      returning 1
    ),
    ins_customers as (
      insert into marketing_roi_customer_facts (
        refresh_run_id, period, customer_id, customer_code, customer_name,
        distributor_code, family_code,
        request_count, marketing_cost, required_roi_value,
        actual_sales_value, actual_sales_units,
        exact_sales_rows, fallback_sales_rows,
        attribution_quality, actual_roi_status,
        source_batch_ids, source_periods, calculation_version
      )
      select
        v_run_id, rr.pay_month, rr.customer_id,
        max(rr.customer_code), max(rr.customer_name),
        rta.distributor_code, max(rta.family_code),
        count(distinct rr.id)::integer,
        sum(rr.estimated_cost * rta.share)::numeric,
        sum(rr.required_roi_value * rta.share)::numeric,
        max(coalesce(acbd.actual_sales_value, 0)),
        max(coalesce(acbd.actual_sales_units, 0)),
        sum(rr.exact_sales_rows)::integer,
        sum(rr.fallback_sales_rows)::integer,
        case when bool_or(rr.attribution_quality = 'no_sales') then 'no_sales' else 'exact_customer' end,
        case
          when bool_or(rr.actual_roi_status = 'no_data') then 'no_data'
          when bool_or(rr.actual_roi_status = 'behind')  then 'behind'
          else 'on_track'
        end,
        v_source_batch_ids, v_affected_periods, '3'
      from request_rows_approved rr
      join request_target_allocations rta on rta.request_id = rr.id
      left join actuals_by_customer_dist acbd
        on acbd.customer_id = rr.customer_id
       and acbd.distributor_code = rta.distributor_code
       and acbd.pay_month = rr.pay_month
      where rr.customer_id is not null
      group by rr.pay_month, rr.customer_id, rta.distributor_code
      returning 1
    )
    select
      (select count(*) from ins_requests)::bigint,
      (select count(*) from ins_trends)::bigint,
      (select count(*) from ins_lines)::bigint,
      (select count(*) from ins_products)::bigint,
      (select count(*) from ins_regions)::bigint,
      (select count(*) from ins_distributors)::bigint,
      (select count(*) from ins_customers)::bigint,
      (select count(*) from ins_request_geo)::bigint
    into
      v_cnt_requests, v_cnt_trends, v_cnt_lines, v_cnt_products,
      v_cnt_regions,  v_cnt_distributors, v_cnt_customers, v_cnt_request_geo;

    update marketing_roi_refresh_runs
    set
      status           = 'success',
      finished_at      = now(),
      affected_periods = v_affected_periods,
      row_counts       = jsonb_build_object(
        'requests', v_cnt_requests, 'trends', v_cnt_trends, 'lines', v_cnt_lines,
        'products', v_cnt_products, 'regions', v_cnt_regions,
        'distributors', v_cnt_distributors, 'customers', v_cnt_customers,
        'requestGeo', v_cnt_request_geo
      )
    where id = v_run_id;

    return jsonb_build_object(
      'status', 'success', 'runId', v_run_id, 'affectedRequests', v_cnt_requests,
      'rowCounts', jsonb_build_object(
        'requests', v_cnt_requests, 'trends', v_cnt_trends, 'lines', v_cnt_lines,
        'products', v_cnt_products, 'regions', v_cnt_regions,
        'distributors', v_cnt_distributors, 'customers', v_cnt_customers,
        'requestGeo', v_cnt_request_geo
      )
    );

  exception when others then
    update marketing_roi_refresh_runs
    set status = 'failed', finished_at = now(), error = sqlerrm,
        affected_periods = v_affected_periods
    where id = v_run_id;
    raise;
  end;
end;
$$;


--
-- TOC entry 882 (class 1255 OID 16684)
-- Name: phx_refresh_sos_customer_directory_rollup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_refresh_sos_customer_directory_rollup(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '60s'
    AS $$
begin
  delete from public.source_of_sales_customer_directory_rollup
  where batch_id = p_batch_id;

  insert into public.source_of_sales_customer_directory_rollup (
    batch_id,
    period,
    distributor_code,
    client_code,
    product_code,
    is_direct,
    client_name,
    client_address,
    brick_id,
    area_code,
    region_code,
    official_line,
    latest_row_created_at,
    effective_units,
    total_qty,
    row_count
  )
  select
    r.batch_id,
    coalesce(nullif(btrim(r.invoice_period), ''), '') as period,
    coalesce(nullif(btrim(r.distributor_code), ''), b.distributor_code, '') as distributor_code,
    nullif(btrim(r.client_code), '') as client_code,
    coalesce(nullif(upper(btrim(r.product_code)), ''), '') as product_code,
    coalesce(r.is_direct, false) as is_direct,
    (array_agg(nullif(btrim(r.client_name), '') order by (nullif(btrim(r.client_name), '') is null), r.created_at desc nulls last))[1] as client_name,
    (array_agg(nullif(btrim(r.client_address), '') order by (nullif(btrim(r.client_address), '') is null), r.created_at desc nulls last))[1] as client_address,
    (array_agg(nullif(btrim(r.brick_id), '') order by (nullif(btrim(r.brick_id), '') is null), r.created_at desc nulls last))[1] as brick_id,
    (array_agg(nullif(btrim(r.area_code), '') order by (nullif(btrim(r.area_code), '') is null), r.created_at desc nulls last))[1] as area_code,
    (array_agg(nullif(btrim(r.region_code), '') order by (nullif(btrim(r.region_code), '') is null), r.created_at desc nulls last))[1] as region_code,
    (array_agg(nullif(btrim(r.official_line), '') order by (nullif(btrim(r.official_line), '') is null), r.created_at desc nulls last))[1] as official_line,
    max(coalesce(r.created_at, b.created_at, 'epoch'::timestamptz)) as latest_row_created_at,
    sum(coalesce(r.qty, 0) * (1 - coalesce(r.discount, 0))) as effective_units,
    sum(coalesce(r.qty, 0)) as total_qty,
    count(*)::integer as row_count
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b
    on b.id = r.batch_id
   and b.status = 'validated'
  where r.batch_id = p_batch_id
    and nullif(btrim(r.client_code), '') is not null
  group by
    r.batch_id,
    coalesce(nullif(btrim(r.invoice_period), ''), ''),
    coalesce(nullif(btrim(r.distributor_code), ''), b.distributor_code, ''),
    nullif(btrim(r.client_code), ''),
    coalesce(nullif(upper(btrim(r.product_code)), ''), ''),
    coalesce(r.is_direct, false);
end;
$$;


--
-- TOC entry 883 (class 1255 OID 16685)
-- Name: phx_refresh_sos_fact_rollup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_refresh_sos_fact_rollup(p_batch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  delete from public.source_of_sales_fact_rollup where batch_id = p_batch_id;
  delete from public.source_of_sales_customer_presence_rollup where batch_id = p_batch_id;

  insert into public.source_of_sales_fact_rollup
    (batch_id, period, distributor_code, official_line, region_code, area_code, brick_id,
     client_code, product_code, product_name, is_direct,
     effective_units, total_qty, total_bonus_qty, direct_value, row_count)
  select
    r.batch_id,
    b.period,
    r.distributor_code,
    r.official_line,
    r.region_code,
    r.area_code,
    r.brick_id,
    r.client_code,
    r.product_code,
    max(r.product_name),
    coalesce(r.is_direct, false),
    sum(r.qty * (1 - coalesce(r.discount, 0))),
    sum(r.qty),
    sum(coalesce(r.bonus_qty, 0)),
    sum(case when coalesce(r.is_direct, false) then r.value else 0 end),
    count(*)
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b
    on b.id = r.batch_id and b.status = 'validated' and r.invoice_period = b.period
  where r.batch_id = p_batch_id
  group by
    r.batch_id, b.period, r.distributor_code, r.official_line, r.region_code,
    r.area_code, r.brick_id, r.client_code, r.product_code, coalesce(r.is_direct, false);

  insert into public.source_of_sales_customer_presence_rollup
    (batch_id, period, client_code, official_line, region_code, present_any, present_nonexcluded)
  select
    r.batch_id,
    b.period,
    r.client_code,
    coalesce(r.official_line, ''),
    coalesce(r.region_code, ''),
    true,
    bool_or(coalesce(upper(btrim(r.product_code)) <> all (array['LA003','LA004','SS001']), false))
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b
    on b.id = r.batch_id and b.status = 'validated' and r.invoice_period = b.period
  where r.batch_id = p_batch_id and r.client_code is not null
  group by
    r.batch_id, b.period, r.client_code, coalesce(r.official_line, ''), coalesce(r.region_code, '');
end;
$$;


--
-- TOC entry 884 (class 1255 OID 16686)
-- Name: phx_release_terminal_manager_ownership(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_release_terminal_manager_ownership(p_previous_hr_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_previous public.employees%rowtype;
  v_upstream_name text;
  v_count integer := 0;
  v_result jsonb := '{}'::jsonb;
begin
  select *
  into v_previous
  from public.employees
  where hr_id = upper(trim(coalesce(p_previous_hr_id, '')));

  if not found then
    return jsonb_build_object('applied', false, 'reason', 'previous_employee_not_found');
  end if;

  if lower(coalesce(v_previous.employment_status, 'active')) not in ('resigned', 'terminated', 'inactive') then
    return jsonb_build_object('applied', false, 'reason', 'previous_employee_not_terminal');
  end if;

  if nullif(trim(coalesce(v_previous.manager_hr_id, '')), '') is null then
    return jsonb_build_object('applied', false, 'reason', 'upstream_manager_missing');
  end if;

  select full_name
  into v_upstream_name
  from public.employees
  where hr_id = v_previous.manager_hr_id;

  update public.employees
  set
    manager_hr_id = v_previous.manager_hr_id,
    pending_manager_replacement_for_hr_id = v_previous.hr_id,
    updated_at = now()
  where manager_hr_id = v_previous.hr_id
    and lower(coalesce(employment_status, 'active')) in ('active', 'on_leave');

  get diagnostics v_count = row_count;
  v_result := v_result || jsonb_build_object('employees_released_to_upstream', v_count);

  update public.position_vacancies
  set
    manager_hr_id = v_previous.manager_hr_id,
    manager_name = v_upstream_name,
    manager_replacement_for_hr_id = v_previous.hr_id,
    note = case
      when coalesce(note, '') ilike '%Pending replacement ownership:%' then note
      else concat_ws(
        E'\n',
        nullif(note, ''),
        'Pending replacement ownership: temporarily moved from terminal manager '
          || v_previous.hr_id || ' to upstream manager ' || v_previous.manager_hr_id
          || ' on ' || current_date::text || '.'
      )
    end,
    updated_at = now()
  where manager_hr_id = v_previous.hr_id
    and lower(coalesce(status, 'open')) = 'open';

  get diagnostics v_count = row_count;
  v_result := v_result || jsonb_build_object('vacancies_released_to_upstream', v_count);

  if to_regclass('public.app_auth_users') is not null then
    begin
      execute
        'update public.app_auth_users
         set manager_hr_id = $2, updated_at = now()
         where manager_hr_id = $1 and is_active is true'
        using v_previous.hr_id, v_previous.manager_hr_id;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('app_auth_users_released_to_upstream', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('app_auth_users_released_to_upstream', null);
    end;
  end if;

  if to_regclass('public.user_access_profiles') is not null then
    begin
      execute
        'update public.user_access_profiles
         set manager_hr_id = $2, updated_at = now()
         where manager_hr_id = $1 and is_active is true'
        using v_previous.hr_id, v_previous.manager_hr_id;

      get diagnostics v_count = row_count;
      v_result := v_result || jsonb_build_object('user_access_profiles_released_to_upstream', v_count);
    exception
      when undefined_column then
        v_result := v_result || jsonb_build_object('user_access_profiles_released_to_upstream', null);
    end;
  end if;

  return jsonb_build_object(
    'applied', true,
    'previous_hr_id', v_previous.hr_id,
    'upstream_manager_hr_id', v_previous.manager_hr_id
  ) || v_result;
end;
$_$;


--
-- TOC entry 885 (class 1255 OID 16687)
-- Name: phx_release_terminal_manager_ownership_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_release_terminal_manager_ownership_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if lower(coalesce(new.employment_status, 'active')) in ('resigned', 'terminated', 'inactive') then
    perform public.phx_release_terminal_manager_ownership(new.hr_id);
  end if;

  return new;
end;
$$;


--
-- TOC entry 886 (class 1255 OID 16688)
-- Name: phx_replace_salary_batch(uuid, integer, integer, text, text, jsonb, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_replace_salary_batch(p_batch_id uuid, p_expected_month integer, p_expected_year integer, p_file_name text, p_uploaded_by text, p_records jsonb, p_flags jsonb, p_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch public.salary_batches%rowtype;
  v_records jsonb := coalesce(p_records, '[]'::jsonb);
  v_flags jsonb := coalesce(p_flags, '[]'::jsonb);
begin
  if jsonb_typeof(v_records) <> 'array' then
    raise exception 'Payroll replacement records must be a JSON array.' using errcode = '22023';
  end if;

  if jsonb_typeof(v_flags) <> 'array' then
    raise exception 'Payroll replacement flags must be a JSON array.' using errcode = '22023';
  end if;

  if jsonb_array_length(v_records) = 0 then
    raise exception 'Payroll replacement records must include at least one salary record.' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_records) as r(payment_mode text)
    where coalesce(r.payment_mode, 'two_parts') not in ('one_part', 'two_parts')
  ) then
    raise exception 'Payroll replacement payment_mode must be one_part or two_parts.' using errcode = '22023';
  end if;

  select *
  into v_batch
  from public.salary_batches
  where id = p_batch_id
  for update;

  if not found then
    raise exception 'Payroll upload not found.' using errcode = 'P0002';
  end if;

  if v_batch.part1_paid_at is not null or v_batch.status not in ('uploaded', 'part1_ready', 'rejected') then
    raise exception 'Payroll batch cannot be replaced after Part 1 is paid or while status is %.', v_batch.status using errcode = 'P0001';
  end if;

  if v_batch.month is distinct from p_expected_month or v_batch.year is distinct from p_expected_year then
    raise exception 'Payroll batch period changed before replacement could be applied.' using errcode = 'P0001';
  end if;

  delete from public.salary_records
  where batch_id = p_batch_id;

  insert into public.salary_records (
    area,
    base_salary,
    batch_id,
    bonus,
    crm,
    employment_income_tax,
    expenses,
    extra_cost_of_living,
    finger_print,
    first_part,
    fuel_allowance,
    full_name,
    governmental_deductions,
    gross_salary,
    hire_date,
    hr_id,
    incentive,
    job_title,
    line,
    loans,
    medical_insurance,
    month_salary,
    name_ar,
    net_salary,
    other_additions,
    other_deductions,
    overtime,
    comment,
    payment_mode,
    second_part,
    social_insurance,
    total_additions,
    total_deductions,
    unpaid_vacations
  )
  select
    r.area,
    coalesce(r.base_salary, 0),
    p_batch_id,
    r.bonus,
    r.crm,
    r.employment_income_tax,
    r.expenses,
    r.extra_cost_of_living,
    r.finger_print,
    r.first_part,
    r.fuel_allowance,
    r.full_name,
    coalesce(r.governmental_deductions, coalesce(r.social_insurance, 0) + coalesce(r.employment_income_tax, 0)),
    r.gross_salary,
    r.hire_date,
    r.hr_id,
    r.incentive,
    r.job_title,
    r.line,
    r.loans,
    r.medical_insurance,
    coalesce(r.month_salary, coalesce(r.first_part, 0) + coalesce(r.second_part, 0)),
    r.name_ar,
    r.net_salary,
    r.other_additions,
    r.other_deductions,
    r.overtime,
    r.comment,
    coalesce(r.payment_mode, 'two_parts'),
    r.second_part,
    r.social_insurance,
    r.total_additions,
    r.total_deductions,
    r.unpaid_vacations
  from jsonb_to_recordset(v_records) as r(
    area text,
    base_salary numeric,
    bonus numeric,
    crm numeric,
    employment_income_tax numeric,
    expenses numeric,
    extra_cost_of_living numeric,
    finger_print numeric,
    first_part numeric,
    fuel_allowance numeric,
    full_name text,
    governmental_deductions numeric,
    gross_salary numeric,
    hire_date date,
    hr_id text,
    incentive numeric,
    job_title text,
    line text,
    loans numeric,
    medical_insurance numeric,
    month_salary numeric,
    name_ar text,
    net_salary numeric,
    other_additions numeric,
    other_deductions numeric,
    overtime numeric,
    comment text,
    payment_mode text,
    second_part numeric,
    social_insurance numeric,
    total_additions numeric,
    total_deductions numeric,
    unpaid_vacations numeric
  );

  delete from public.salary_flags
  where batch_id = p_batch_id;

  insert into public.salary_flags (
    batch_id,
    flag_type,
    hr_id,
    message,
    severity
  )
  select
    p_batch_id,
    f.flag_type,
    f.hr_id,
    f.message,
    coalesce(f.severity, 'warning')
  from jsonb_to_recordset(v_flags) as f(
    flag_type text,
    hr_id text,
    message text,
    severity text
  );

  update public.salary_batches
  set
    approved_at = null,
    approved_by = null,
    file_name = p_file_name,
    locked_at = null,
    part1_paid_at = null,
    part1_paid_by = null,
    part2_ready_at = null,
    part2_ready_by = null,
    rejected_reason = null,
    status = 'uploaded',
    updated_at = p_updated_at,
    uploaded_by = p_uploaded_by
  where id = p_batch_id
  returning *
  into v_batch;

  return to_jsonb(v_batch);
end;
$$;


