--
-- TOC entry 889 (class 1255 OID 16695)
-- Name: phx_save_attendance_policy(bigint, text, text, text, text, text, integer, date, date, boolean, smallint[], jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_save_attendance_policy(p_id bigint, p_policy_name text, p_target_type text, p_target_value text, p_sched_start text, p_sched_end text, p_grace_minutes integer, p_effective_from date, p_effective_to date, p_is_active boolean, p_weekdays smallint[], p_rules jsonb, p_now timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id bigint;
BEGIN
  IF p_id IS NOT NULL THEN
    UPDATE attendance_policy_groups SET
      policy_name      = p_policy_name,
      target_type      = p_target_type,
      target_value     = p_target_value,
      scheduled_start  = p_sched_start::time,
      scheduled_end    = p_sched_end::time,
      grace_minutes    = p_grace_minutes,
      effective_from   = p_effective_from,
      effective_to     = p_effective_to,
      is_active        = p_is_active,
      working_weekdays = p_weekdays,
      updated_at       = p_now
    WHERE id = p_id;
    v_id := p_id;
  ELSE
    INSERT INTO attendance_policy_groups (
      policy_name, target_type, target_value, scheduled_start, scheduled_end,
      grace_minutes, effective_from, effective_to, is_active, working_weekdays,
      created_at, updated_at
    ) VALUES (
      p_policy_name, p_target_type, p_target_value,
      p_sched_start::time, p_sched_end::time,
      p_grace_minutes, p_effective_from, p_effective_to, p_is_active, p_weekdays,
      p_now, p_now
    )
    RETURNING id INTO v_id;
  END IF;

  -- Atomically replace rules — the delete+insert pair is inside this transaction,
  -- so there is no window where the policy can have zero rules.
  DELETE FROM attendance_policy_rules WHERE policy_id = v_id;

  INSERT INTO attendance_policy_rules (
    policy_id, event_type, from_minutes, to_minutes, recommended_action,
    deduction_days, deduction_value, is_active, sort_order, updated_at
  )
  SELECT
    v_id,
    (r->>'event_type')::text,
    NULLIF(r->>'from_minutes', '')::integer,
    NULLIF(r->>'to_minutes',   '')::integer,
    (r->>'recommended_action')::text,
    NULLIF(r->>'deduction_days',  '')::numeric,
    NULLIF(r->>'deduction_value', '')::numeric,
    COALESCE((r->>'is_active')::boolean, true),
    (r->>'sort_order')::integer,
    p_now
  FROM jsonb_array_elements(p_rules) AS r
  WHERE (r->>'event_type') IS NOT NULL;

  RETURN v_id;
END;
$$;


--
-- TOC entry 890 (class 1255 OID 16696)
-- Name: phx_si_brick(text, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_si_brick(p_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT '{}'::text[], p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[]) RETURNS TABLE(distributor_code text, region_code text, area_code text, brick_id text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select
    f.distributor_code,
    f.region_code,
    f.area_code,
    f.brick_id,
    sum(f.total_qty) as units,
    sum(f.effective_units * coalesce(p.factory_price, 0)) as value
  from public.source_of_sales_fact_rollup f
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  where (p_period is null or f.period = p_period)
    and f.is_direct = false
    and upper(btrim(coalesce(f.product_code, ''))) <> all (
      select upper(btrim(c)) from unnest(p_exclude_codes) as c
    )
    and (
      cardinality(p_lines) = 0
      or lower(btrim(coalesce(f.official_line, ''))) in (select lower(btrim(x)) from unnest(p_lines) as x)
    )
    and (
      cardinality(p_regions) = 0
      or lower(btrim(coalesce(f.region_code, ''))) in (select lower(btrim(x)) from unnest(p_regions) as x)
    )
  group by f.distributor_code, f.region_code, f.area_code, f.brick_id;
$$;


--
-- TOC entry 891 (class 1255 OID 16697)
-- Name: phx_si_customer_product(text, text[], text[], text[], text[], text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_si_customer_product(p_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT '{}'::text[], p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[], p_product_codes text[] DEFAULT '{}'::text[], p_client_codes text[] DEFAULT '{}'::text[], p_limit integer DEFAULT 100) RETURNS TABLE(client_code text, client_name text, distributor_code text, region_code text, area_code text, product_code text, product_name text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with scoped as (
    select
      r.client_code, r.client_name, r.distributor_code, r.region_code, r.area_code,
      r.product_code, p.product_name, r.total_qty,
      r.effective_units * coalesce(p.factory_price, 0) as line_value
    from public.source_of_sales_customer_directory_rollup r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
    where (cardinality(p_product_codes) > 0 or cardinality(p_client_codes) > 0)
      and (p_period is null or r.period = p_period)
      and r.client_code is not null
      and r.is_direct = false
      and upper(btrim(coalesce(r.product_code, ''))) <> all (
        select upper(btrim(c)) from unnest(p_exclude_codes) as c
      )
      and (
        cardinality(p_lines) = 0
        or lower(btrim(coalesce(r.official_line, ''))) in (select lower(btrim(x)) from unnest(p_lines) as x)
      )
      and (
        cardinality(p_regions) = 0
        or lower(btrim(coalesce(r.region_code, ''))) in (select lower(btrim(x)) from unnest(p_regions) as x)
      )
      and (
        cardinality(p_product_codes) = 0
        or upper(btrim(r.product_code)) in (select upper(btrim(x)) from unnest(p_product_codes) as x)
      )
      and (
        cardinality(p_client_codes) = 0
        or upper(btrim(r.client_code)) in (select upper(btrim(x)) from unnest(p_client_codes) as x)
      )
  )
  select
    s.client_code,
    max(s.client_name) as client_name,
    s.distributor_code,
    max(s.region_code) as region_code,
    max(s.area_code) as area_code,
    s.product_code,
    max(s.product_name) as product_name,
    sum(s.total_qty) as units,
    sum(s.line_value) as value
  from scoped s
  group by s.client_code, s.distributor_code, s.product_code
  order by sum(s.line_value) desc
  limit greatest(1, least(coalesce(p_limit, 100), 500));
$$;


--
-- TOC entry 892 (class 1255 OID 16698)
-- Name: phx_si_customers(text, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_si_customers(p_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT '{}'::text[], p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[]) RETURNS TABLE(client_code text, client_name text, distributor_code text, region_code text, area_code text, brick_id text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with filtered as (
    select
      r.client_code, r.client_name, r.distributor_code, r.region_code, r.area_code, r.brick_id,
      r.product_code, r.latest_row_created_at, r.total_qty,
      r.effective_units * coalesce(p.factory_price, 0) as line_value
    from public.source_of_sales_customer_directory_rollup r
    join public.source_of_sales_import_batches b
      on b.id = r.batch_id and b.status = 'validated'
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
    where (p_period is null or r.period = p_period)
      and r.client_code is not null
      and r.is_direct = false
      and upper(btrim(coalesce(r.product_code, ''))) <> all (
        select upper(btrim(c)) from unnest(p_exclude_codes) as c
      )
      and (
        cardinality(p_lines) = 0
        or lower(btrim(coalesce(r.official_line, ''))) in (select lower(btrim(x)) from unnest(p_lines) as x)
      )
      and (
        cardinality(p_regions) = 0
        or lower(btrim(coalesce(r.region_code, ''))) in (select lower(btrim(x)) from unnest(p_regions) as x)
      )
  ),
  latest as (
    -- product_code is a deterministic secondary tiebreak for the rare case where two rows
    -- for the same client+distributor share the exact same latest_row_created_at (observed
    -- in production parity testing: two product lines imported in the same batch, identical
    -- timestamp to the microsecond). Without it, which row "wins" is Postgres-plan-dependent
    -- and can vary run to run; this makes the pick reproducible. Only affects the tied case —
    -- verified against production data to be a no-op everywhere the timestamp already differs.
    select distinct on (client_code, distributor_code)
      client_code, distributor_code, client_name, region_code, area_code, brick_id
    from filtered
    order by client_code, distributor_code, latest_row_created_at desc, product_code asc
  ),
  agg as (
    select client_code, distributor_code, sum(total_qty) as units, sum(line_value) as value
    from filtered
    group by client_code, distributor_code
  )
  select a.client_code, l.client_name, a.distributor_code, l.region_code, l.area_code, l.brick_id, a.units, a.value
  from agg a
  join latest l using (client_code, distributor_code);
$$;


--
-- TOC entry 893 (class 1255 OID 16699)
-- Name: phx_si_daily(text, text[], text[], text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_si_daily(p_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT '{}'::text[], p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[], p_product_codes text[] DEFAULT '{}'::text[], p_distributor_codes text[] DEFAULT '{}'::text[]) RETURNS TABLE(invoice_date date, distributor_code text, units numeric, value numeric, customer_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select
    r.invoice_date,
    r.distributor_code,
    sum(r.qty) as units,
    sum(case when coalesce(r.is_direct, false)
             then r.value
             else r.qty * (1 - coalesce(r.discount, 0)) * coalesce(p.factory_price, 0) end) as value,
    count(distinct r.client_code)::integer as customer_count
  from public.source_of_sales_import_rows r
  join public.source_of_sales_import_batches b on b.id = r.batch_id
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
  where p_period is not null
    and b.status = 'validated' and r.invoice_period = b.period
    and b.period = p_period
    and upper(btrim(r.product_code)) <> all (
      select upper(btrim(c)) from unnest(p_exclude_codes) as c
    )
    and (
      cardinality(p_lines) = 0
      or lower(btrim(r.official_line)) in (select lower(btrim(x)) from unnest(p_lines) as x)
    )
    and (
      cardinality(p_regions) = 0
      or lower(btrim(r.region_code)) in (select lower(btrim(x)) from unnest(p_regions) as x)
    )
    and (
      cardinality(p_product_codes) = 0
      or upper(btrim(r.product_code)) in (select upper(btrim(x)) from unnest(p_product_codes) as x)
    )
    and (
      cardinality(p_distributor_codes) = 0
      or upper(btrim(r.distributor_code)) in (select upper(btrim(x)) from unnest(p_distributor_codes) as x)
    )
  group by r.invoice_date, r.distributor_code;
$$;


--
-- TOC entry 894 (class 1255 OID 16700)
-- Name: phx_si_distributor_product(text, text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_si_distributor_product(p_period text DEFAULT NULL::text, p_exclude_codes text[] DEFAULT '{}'::text[], p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[]) RETURNS TABLE(distributor_code text, official_line text, region_code text, area_code text, product_code text, product_name text, units numeric, value numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  select
    f.distributor_code,
    f.official_line,
    f.region_code,
    coalesce(nullif(f.area_code, ''), 'DIRECT') as area_code,
    f.product_code,
    max(f.product_name)                         as product_name,
    sum(f.total_qty)                            as units,
    sum(case when f.is_direct
             then f.direct_value
             else f.effective_units * coalesce(p.factory_price, 0) end) as value
  from public.source_of_sales_fact_rollup f
  join public.source_of_sales_import_batches b
    on b.id = f.batch_id and b.status = 'validated'
  left join public.source_of_sales_products p
    on upper(btrim(p.product_code)) = upper(btrim(f.product_code))
  where (p_period is null or f.period = p_period)
    and (
      cardinality(p_exclude_codes) = 0
      or upper(btrim(f.product_code)) <> all (
        select upper(btrim(c)) from unnest(p_exclude_codes) as c
      )
    )
    and (
      cardinality(p_lines) = 0
      or lower(btrim(f.official_line)) in (select lower(btrim(x)) from unnest(p_lines) as x)
    )
    and (
      cardinality(p_regions) = 0
      or lower(btrim(f.region_code)) in (select lower(btrim(x)) from unnest(p_regions) as x)
    )
  group by f.distributor_code, f.official_line, f.region_code,
           coalesce(nullif(f.area_code, ''), 'DIRECT'), f.product_code;
$$;


--
-- TOC entry 895 (class 1255 OID 16701)
-- Name: phx_si_period_totals(text[], text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_si_period_totals(p_exclude_codes text[] DEFAULT '{}'::text[], p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[]) RETURNS TABLE(period text, units numeric, value numeric, customer_count integer, product_count integer, area_count integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    SET statement_timeout TO '45s'
    AS $$
  with flt as (
    select
      r.period,
      r.total_qty,
      r.effective_units,
      r.direct_value,
      r.is_direct,
      r.product_code,
      r.area_code,
      coalesce(p.factory_price, 0) as factory_price
    from public.source_of_sales_fact_rollup r
    left join public.source_of_sales_products p
      on upper(btrim(p.product_code)) = upper(btrim(r.product_code))
    where upper(btrim(r.product_code)) <> all (
        select upper(btrim(c)) from unnest(p_exclude_codes) as c
      )
      and (
        cardinality(p_lines) = 0
        or lower(btrim(r.official_line)) in (select lower(btrim(x)) from unnest(p_lines) as x)
      )
      and (
        cardinality(p_regions) = 0
        or lower(btrim(r.region_code)) in (select lower(btrim(x)) from unnest(p_regions) as x)
      )
  ),
  val as (
    select
      period,
      sum(total_qty) as units,
      sum(case when is_direct then direct_value else effective_units * factory_price end) as value,
      count(distinct upper(btrim(product_code)))::integer as product_count,
      count(distinct nullif(btrim(area_code), ''))::integer as area_count
    from flt
    group by period
  ),
  cust as (
    select
      c.period,
      count(distinct c.client_code)::integer as customer_count
    from public.source_of_sales_customer_presence_rollup c
    where (case when cardinality(p_exclude_codes) = 0 then c.present_any else c.present_nonexcluded end)
      and (
        cardinality(p_lines) = 0
        or lower(btrim(c.official_line)) in (select lower(btrim(x)) from unnest(p_lines) as x)
      )
      and (
        cardinality(p_regions) = 0
        or lower(btrim(c.region_code)) in (select lower(btrim(x)) from unnest(p_regions) as x)
      )
    group by c.period
  )
  select
    v.period,
    v.units,
    v.value,
    coalesce(cu.customer_count, 0) as customer_count,
    v.product_count,
    v.area_count
  from val v
  left join cust cu on cu.period = v.period;
$$;


--
-- TOC entry 896 (class 1255 OID 16702)
-- Name: phx_sos_distinct_distributors(text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_sos_distinct_distributors(p_lines text[] DEFAULT '{}'::text[], p_regions text[] DEFAULT '{}'::text[]) RETURNS TABLE(distributor_code text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
