--
-- TOC entry 918 (class 1255 OID 16726)
-- Name: phx_weekly_plan_submit(uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_weekly_plan_submit(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status text;
  current_revision integer;
  next_status text;
  now_ts timestamptz := now();
begin
  -- Optimistic lock: SELECT FOR UPDATE blocks concurrent transitions on this
  -- header row. expected_revision must match the current revision or we
  -- raise a typed conflict exception that the TS layer maps to HTTP 409.
  select status, revision into current_status, current_revision
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  next_status := public.phx_weekly_plan_next_status(current_status, 'submit', true);

  update public.employee_plan_headers
    set status = next_status,
        submitted_at = coalesce(submitted_at, now_ts),
        submitted_by_login_id = coalesce(submitted_by_login_id, p_actor_login_id),
        revision = revision + 1,
        updated_at = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role, 'submit', current_status, next_status, null);

  return query select next_status, current_revision + 1;
end;
$$;


--
-- TOC entry 919 (class 1255 OID 16727)
-- Name: phx_weekly_plan_submit_details(uuid, integer, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_weekly_plan_submit_details(p_plan_id uuid, p_expected_revision integer, p_actor_hr_id text, p_actor_login_id text, p_actor_role text, p_visit_details jsonb) RETURNS TABLE(new_status text, new_revision integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  current_status   text;
  current_revision integer;
  now_ts           timestamptz := now();
  detail           jsonb;
  item_id_val      uuid;
begin
  select status, revision
    into current_status, current_revision
    from public.employee_plan_headers
    where id = p_plan_id
    for update;

  if current_status is null then
    raise exception 'weekly_plan_not_found: plan % does not exist', p_plan_id using errcode = 'P0001';
  end if;

  if current_revision <> p_expected_revision then
    raise exception 'weekly_plan_revision_conflict: expected revision % but found %', p_expected_revision, current_revision using errcode = 'P0001';
  end if;

  -- Validate transition.
  perform public.phx_weekly_plan_next_status(current_status, 'submit_visit_details', false);

  -- Wipe existing visit details for this plan (clean slate on every submission).
  delete from public.employee_plan_visit_details
    where plan_id = p_plan_id;

  -- Insert the new set, validating each item belongs to this plan and is a Field row.
  for detail in select * from jsonb_array_elements(p_visit_details)
  loop
    item_id_val := (detail->>'itemId')::uuid;

    if not exists (
      select 1 from public.employee_plan_items
        where id = item_id_val
          and plan_id = p_plan_id
          and activity_type = 'Field'
    ) then
      raise exception 'weekly_plan_invalid_transition: item % is not a Field item belonging to plan %',
        detail->>'itemId', p_plan_id using errcode = 'P0001';
    end if;

    insert into public.employee_plan_visit_details
      (plan_id, item_id, doctor_name, speciality, address, objective, sort_order)
      values (
        p_plan_id,
        item_id_val,
        detail->>'doctorName',
        detail->>'speciality',
        detail->>'address',
        detail->>'objective',
        coalesce((detail->>'sortOrder')::integer, 0)
      );
  end loop;

  -- Advance the plan back to submitted.
  update public.employee_plan_headers
    set status     = 'submitted',
        revision   = revision + 1,
        updated_at = now_ts
    where id = p_plan_id;

  insert into public.employee_plan_decisions
    (plan_id, actor_hr_id, actor_login_id, actor_role, action, from_status, to_status, comment)
    values
    (p_plan_id, p_actor_hr_id, p_actor_login_id, p_actor_role,
     'submit_visit_details', current_status, 'submitted', null);

  return query select 'submitted'::text, current_revision + 1;
end;
$$;


--
-- TOC entry 920 (class 1255 OID 16728)
-- Name: phx_weekly_plans_drift_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.phx_weekly_plans_drift_check() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  d1_count integer := 0;
  d2_count integer := 0;
  d3_count integer := 0;
  d4_count integer := 0;
  d5_count integer := 0;
  d6_count integer := 0;
BEGIN
  -- D1: final_approved but no timestamp
  SELECT COUNT(*) INTO d1_count
  FROM employee_plan_headers
  WHERE status = 'final_approved' AND final_approved_at IS NULL;

  -- D2: advanced status but no submitted_at
  SELECT COUNT(*) INTO d2_count
  FROM employee_plan_headers
  WHERE status IN (
    'submitted', 'manager_approved', 'manager_rejected', 'manager_returned',
    'ceo_approved', 'ceo_rejected', 'ceo_returned', 'final_approved', 'hr_acknowledged'
  ) AND submitted_at IS NULL;

  -- D3: manager decision actor/timestamp XOR
  SELECT COUNT(*) INTO d3_count
  FROM employee_plan_headers
  WHERE (manager_decision_by_hr_id IS NULL) <> (manager_decision_at IS NULL);

  -- D4: orphan plans awaiting manager with NULL/missing/terminated manager
  SELECT COUNT(*) INTO d4_count
  FROM employee_plan_headers h
  LEFT JOIN employees e ON UPPER(e.hr_id) = UPPER(h.manager_hr_id)
  WHERE h.status IN ('submitted', 'manager_returned', 'ceo_returned')
    AND (h.manager_hr_id IS NULL OR e.hr_id IS NULL
         OR e.employment_status NOT IN ('active', 'on_leave'));

  -- D5: header status mismatched with most recent decision row
  SELECT COUNT(*) INTO d5_count
  FROM employee_plan_headers h
  JOIN LATERAL (
    SELECT to_status FROM employee_plan_decisions d
    WHERE d.plan_id = h.id ORDER BY created_at DESC LIMIT 1
  ) d ON true
  WHERE h.status <> d.to_status;

  -- D6: hr_acknowledged header but no acknowledgement row
  SELECT COUNT(*) INTO d6_count
  FROM employee_plan_headers h
  LEFT JOIN employee_plan_hr_acknowledgements a ON a.plan_id = h.id
  WHERE h.status = 'hr_acknowledged' AND a.id IS NULL;

  RETURN jsonb_build_object(
    'D1', d1_count,
    'D2', d2_count,
    'D3', d3_count,
    'D4', d4_count,
    'D5', d5_count,
    'D6', d6_count
  );
END;
$$;


