--
-- TOC entry 654 (class 1259 OID 41380)
-- Name: closing_fact; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.closing_fact AS
 SELECT r.year,
    r.month,
    lpad((r.month)::text, 2, '0'::text) AS month_str,
    (((r.year)::text || '-'::text) || lpad((r.month)::text, 2, '0'::text)) AS period,
    b.id AS batch_id,
    b.file_name AS batch_file,
    b.status AS batch_status,
    b.line,
    r.employee_hr_id,
    r.employee_name,
    r.manager_hr_id,
    r.territory,
    r.sales_type,
    r.product,
    r.family,
    r.sales_units,
    r.sales_value,
    r.target_units,
    r.target_value,
    r.validation_state,
    r.link_status,
        CASE
            WHEN (r.target_value > (0)::numeric) THEN round(((r.sales_value / r.target_value) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS achievement_pct,
    p.product_code
   FROM ((public.sales_records r
     LEFT JOIN public.sales_import_batches b ON ((b.id = r.batch_id)))
     LEFT JOIN LATERAL ( SELECT sp.product_code
           FROM public.source_of_sales_products sp
          WHERE (lower(btrim(sp.product_name)) = lower(btrim(r.product)))
          ORDER BY sp.active DESC, sp.product_code
         LIMIT 1) p ON (true))
  WHERE ((b.status = 'approved'::text) AND (lower(btrim(r.product)) <> ALL (ARRAY['lacto basic 1'::text, 'lacto basic 2'::text, 'satoslim'::text])));


