--
-- TOC entry 387 (class 1259 OID 20335)
-- Name: coaching_reports_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.coaching_reports_summary WITH (security_invoker='true') AS
 SELECT r.id AS report_id,
    r.report_number,
    rep.full_name AS medical_rep_name,
    r.medical_rep_hr_id,
    coach.full_name AS coach_name,
    r.coach_hr_id,
    l.name AS line_name,
    a.name AS area_name,
    t.name AS team_name,
    r.coaching_date,
    r.coaching_month,
    r.coaching_quarter,
    r.coaching_year,
    r.actual_score,
    r.max_score,
    r.final_score_percent,
    r.performance_zone,
    r.status,
    r.employee_acknowledged AS acknowledged,
    r.acknowledged_at,
    r.submitted_at,
    r.created_at,
    r.updated_at,
    r.line_id,
    r.area_id,
    r.team_id
   FROM (((((public.coaching_reports r
     JOIN public.employees rep ON ((rep.hr_id = r.medical_rep_hr_id)))
     JOIN public.employees coach ON ((coach.hr_id = r.coach_hr_id)))
     LEFT JOIN public.lines l ON ((l.id = r.line_id)))
     LEFT JOIN public.areas a ON ((a.id = r.area_id)))
     LEFT JOIN public.teams t ON ((t.id = r.team_id)));


